    '. Aplica a la liga' => '. Vale per la lega',
    '. Aplica a la plataforma' => '. Vale per la piattaforma',
    '. Cada campeonato copia estas reglas al crearse y después se pueden cambiar solo para ese campeonato (Campeonatos → el campeonato → Configuración). Su contraseña y la doble verificación están en' => '. Ogni campionato copia queste regole alla creazione e poi si possono modificare solo per quel campionato (Campionati → il campionato → Impostazioni). La Sua password e la verifica in due passaggi si trovano in',
    '. Cada campeonato nuevo empieza con ellas, pero cada campeonato puede tener las suyas (se cambian en Campeonato → Configuración).' => '. Ogni nuovo campionato parte con queste, ma ogni campionato può avere le proprie (si modificano in Campionato → Impostazioni).',
    '. Cada cono suma {n} s automáticamente. Toque' => '. Ogni cono aggiunge automaticamente {n} s. Tocchi',
    '. Cuando una liga se registra con su enlace o su código (o usted la asigna en Ligas → Editar), cada pago de suscripción que registre en' => '. Quando una lega si registra con il suo link o il suo codice (o Lei la assegna in Leghe → Modifica), ogni pagamento di abbonamento che registra in',
    '. Deje vacío a quien no jugó.' => '. Lasci vuoto chi non ha giocato.',
    '. Ejemplo, sprint de {n} m (gana el menor), {n} a {n} años: amarillo desde {n} s y verde desde {n} s.' => '. Esempio, sprint di {n} m (vince il minore), da {n} a {n} anni: giallo da {n} s e verde da {n} s.',
    '. El ganador pasa solo a la ronda siguiente.' => '. Il vincitore passa automaticamente al turno successivo.',
    '. El interesado llena "Solicitar demo" y usted decide a quién le crea la cuenta (menú' => '. L\'interessato compila "Richiedi demo" e Lei decide a chi creare l\'account (menu',
    '. El público lo ve en la pestaña' => '. Il pubblico lo vede nella scheda',
    '. En el celular:' => '. Dal cellulare:',
    '. En el celular: menú ⋮ → Compartir → Imprimir → Guardar como PDF.' => '. Dal cellulare: menu ⋮ → Condividi → Stampa → Salva come PDF.',
    '. Estos proveedores aplican medidas de seguridad reconocidas internacionalmente y actúan solo como proveedores de infraestructura: no usan los datos para fines propios. Al aceptar esta política, usted autoriza esta transferencia internacional, que es necesaria para que el servicio funcione.' => '. Questi fornitori applicano misure di sicurezza riconosciute a livello internazionale e agiscono solo come fornitori di infrastruttura: non usano i dati per fini propri. Accettando questa informativa, Lei autorizza questo trasferimento internazionale, necessario per il funzionamento del servizio.',
    '. Falta que la federación lo apruebe.' => '. Manca l\'approvazione della federazione.',
    '. Formulario público:' => '. Modulo pubblico:',
    '. Funciona sin internet y sincroniza cuando vuelve la señal.' => '. Funziona senza internet e si sincronizza quando torna il segnale.',
    '. La cédula se valida ({n} números) o se acepta pasaporte.' => '. Il documento d\'identità viene convalidato ({n} cifre) oppure si accetta il passaporto.',
    '. La federación ve sus números, sus partidos y puede poner sanciones federativas que se aplican en sus campeonatos. Sus torneos siguen siendo solo suyos.' => '. La federazione vede i suoi numeri, le sue partite e può imporre sanzioni federali che si applicano nei suoi campionati. I suoi tornei restano solo suoi.',
    '. La liga la abre en cada campeonato con una fecha límite.' => '. La lega la apre in ogni campionato con una data limite.',
    '. Le pediremos su cédula para comprobar que es el titular. Se responderá en el plazo que establece la ley ({n} días).' => '. Le chiederemo il Suo documento d\'identità per verificare che sia il titolare. La risposta sarà fornita entro il termine previsto dalla legge ({n} giorni).',
    '. Los árbitros y delegados se crean en Árbitros y en cada Equipo.' => '. Gli arbitri e i dirigenti si creano in Arbitri e in ogni Squadra.',
    '. Mientras más claro, más rápido lo podemos evaluar y desarrollar. Le avisamos aquí cuando tengamos novedades.' => '. Più è chiaro, più in fretta potremo valutarlo e svilupparlo. La avviseremo qui quando avremo novità.',
    '. No ve los pagos de los alumnos; sí ve' => '. Non vede i pagamenti degli allievi; vede invece',
    '. Para salir de un panel y entrar a otro, vuelva a esta página.' => '. Per uscire da un pannello ed entrare in un altro, torni a questa pagina.',
    '. Quien entra por su enlace queda anotado como recomendado por usted.' => '. Chi si iscrive tramite il Suo link viene registrato come segnalato da Lei.',
    '. Recibimos su solicitud de demo para' => '. Abbiamo ricevuto la Sua richiesta di demo per',
    '. Revise el correo (será su usuario) y los días de la demo.' => '. Controlli l\'e-mail (sarà il suo nome utente) e i giorni della demo.',
    '. Se rige por la Ley Orgánica de Protección de Datos Personales del Ecuador (LOPDP) y su Reglamento.' => '. È regolato dalla Legge Organica sulla Protezione dei Dati Personali dell\'Ecuador (LOPDP) e dal relativo Regolamento.',
    '. Si deja vacío y pone el estado "Finalizado", se llenan solos.' => '. Se lascia vuoto e imposta lo stato "Terminato", si compilano da soli.',
    '. Si no compitió, cambie el estado (DNS, DNF o DQ). Los puestos se calculan solos.' => '. Se non ha gareggiato, cambi lo stato (DNS, DNF o DQ). Le posizioni si calcolano da sole.',
    '. Si quiere vender las entradas de sus partidos (con QR, tarjeta o transferencia, taquilla, cortesías y parqueadero), actívela con la casilla en' => '. Se desidera vendere i biglietti delle sue partite (con QR, carta o bonifico, botteghino, omaggi e parcheggio), la attivi con la casella in',
    '. Si su escuela es recreativa, déjelo apagado: el menú queda más simple.' => '. Se la sua scuola è ricreativa, lo lasci disattivato: il menu resta più semplice.',
    '. También se puede subir después.' => '. Si può caricare anche dopo.',
    '. Tarea automática: última vez' => '. Attività automatica: ultima volta',
    '. Toque' => '. Tocchi',
    '. Usted aprueba o rechaza con una respuesta; todo queda registrado y sale en el boletín de la fecha.' => '. Lei approva o respinge con una risposta; tutto viene registrato e compare nel bollettino della giornata.',
    '. iPhone (Safari): botón compartir' => '. iPhone (Safari): pulsante condividi',
    '. ¿Le parece si se la activo ahora y le explico en {n} minutos cómo funciona?' => '. Se desidera, la attivo ora e Le spiego in {n} minuti come funziona.',
    '. Ábrala abajo para que los competidores se inscriban solos desde la página pública.' => '. La apra qui sotto perché i concorrenti si iscrivano da soli dalla pagina pubblica.',
