    ': el premio lo pone un patrocinador (camiseta, cena, recarga…). Hace que la gente entre a la página todas las semanas, y eso le da más vistas a sus patrocinadores.' => ': il premio lo offre uno sponsor (maglia, cena, ricarica…). Fa sì che le persone visitino la pagina ogni settimana, e questo dà più visualizzazioni ai Suoi sponsor.',
