    'Al cargar los tiempos, en cada etapa se marca cuántas veces se aplicó cada una y el sistema suma (o resta) los segundos. Use un valor negativo para una bonificación (ej: meta volante −{n}). Si cambia un valor, las clasificaciones se recalculan.' => 'Al caricamento dei tempi, in ogni tappa si indica quante volte è stata applicata ciascuna e il sistema somma (o sottrae) i secondi. Usi un valore negativo per un bonus (es.: traguardo volante −{n}). Se modifica un valore, le classifiche vengono ricalcolate.',
    'Al cargar los tiempos, en cada manga se marca cuántas veces se aplicó cada una y el sistema suma (o resta) los segundos. Use un valor negativo para una bonificación (ej: meta volante −{n}). Si cambia un valor, las clasificaciones se recalculan.' => 'Al caricamento dei tempi, in ogni manche si indica quante volte è stata applicata ciascuna e il sistema somma (o sottrae) i secondi. Usi un valore negativo per un bonus (es.: traguardo volante −{n}). Se modifica un valore, le classifiche vengono ricalcolate.',
