    'Al terminar la fase regular, el sistema arma la llave con los mejores de la tabla ({n} grupos): el {n}º contra el último clasificado, y los de un mismo grupo no se cruzan en la primera ronda.' => 'Al termine della fase regolare, il sistema crea il tabellone con i migliori della classifica ({n} gruppi): il {n}º contro l\'ultimo qualificato, e quelli dello stesso gruppo non si incrociano al primo turno.',
