    'Con el combo liga + escuela maneja las dos con el mismo usuario y paga {n}% menos en cada plan.' => 'Con il combo lega + scuola gestisce entrambe con lo stesso utente e paga il {n}% in meno su ciascun piano.',
    'Con el plan' => 'Con il piano',
    'Con el plan Profesional imprime el fixture completo de cada campeonato (con o sin resultados) y ve el esquema de todo el torneo desde el primer día: grupos, jornadas y la llave de la fase final con los cruces, que se llenan solos con los clasificados.' => 'Con il piano Professionale stampa il calendario completo di ogni campionato (con o senza risultati) e vede lo schema di tutto il torneo fin dal primo giorno: gruppi, giornate e il tabellone della fase finale con gli accoppiamenti, che si riempiono da soli con i qualificati.',
    'Con este enlace, cualquiera agrega todos los partidos del campeonato al calendario de su celular (y se actualiza solo). Cada equipo tiene el suyo en su página pública.' => 'Con questo link, chiunque può aggiungere tutte le partite del campionato al calendario del proprio cellulare (e si aggiorna da solo). Ogni squadra ha il proprio nella sua pagina pubblica.',
    'Con la misma cédula se agrupan hermanos (descuento).' => 'Con lo stesso documento d\'identità i fratelli vengono raggruppati (sconto).',
    'Con las marcadas:' => 'Con quelle selezionate:',
    'Con menos, el equipo pierde por W.O.' => 'Con meno, la squadra perde a tavolino.',
    'Con parqueadero' => 'Con parcheggio',
    'Con su correo y contraseña, el delegado entra a' => 'Con e-mail e password, il dirigente accede a',
    'Con su usuario toma la asistencia, anota el plan de clase y registra medidas, tests y evaluaciones' => 'Con il suo utente rileva le presenze, annota il piano di lezione e registra misure, test e valutazioni',
    'Con un plan pagado puede subir de una sola vez todos sus' => 'Con un piano a pagamento può caricare in una sola volta tutti i Suoi',
    'Con un plan pagado puede subir de una sola vez todos sus equipos, jugadores, árbitros, canchas y competidores desde Excel, y descargar una copia de todos sus datos cuando quiera.' => 'Con un piano a pagamento può caricare in una sola volta tutte le sue squadre, giocatori, arbitri, campi e concorrenti da Excel, e scaricare una copia di tutti i suoi dati quando vuole.',
    'Con y sin factura' => 'Con e senza fattura',
