    'Cuando la organización ingresa en el sistema los datos de otra persona (por ejemplo, al inscribir a un jugador o importar una lista), declara contar con la autorización de esa persona o de su representante, y esa declaración también queda registrada.' => 'Quando l\'organizzazione inserisce nel sistema i dati di un\'altra persona (ad esempio, iscrivendo un giocatore o importando un elenco), dichiara di disporre dell\'autorizzazione di tale persona o del suo rappresentante legale, e anche questa dichiarazione viene registrata.',
    'Cuando las clases tengan ejercicios, aquí verá cuánto tiempo fue técnico, táctico, físico o juego.' => 'Quando le lezioni avranno esercizi, qui vedrà quanto tempo è stato tecnico, tattico, fisico o di gioco.',
