    'Cuando un alumno está en otro grupo (otro deporte), esa mensualidad lleva este descuento.' => 'Quando un allievo è in un altro gruppo (altro sport), questa quota mensile ha questo sconto.',
    'Cuartos de final' => 'Quarti di finale',
