    'Ej: {n}er quimestre {n}' => 'Es.: {n}º quimestre {n}',
    'Ej: «en Finanzas» o «en la página pública de la liga».' => 'Es.: «in Finanze» o «nella pagina pubblica della lega».',
    'Ej: «en un Excel» o «a mano en un cuaderno».' => 'Es.: «in un Excel» o «a mano su un quaderno».',
    'Ej: «hoy los delegados me mandan las fotos por WhatsApp y se me pierden».' => 'Es.: «oggi i dirigenti mi mandano le foto su WhatsApp e le perdo».',
    'Ej: ¿Quién fue el mejor jugador de la final?' => 'Es.: Chi è stato il miglior giocatore della finale?',
    'Ejemplo' => 'Esempio',
    'Ejemplo, sprint de 30 m (gana el menor), 10 a 11 años: amarillo desde 5,9 s y verde desde 5,4 s → 5,3 s es verde, 5,7 s es amarillo y 6,1 s es rojo.' => 'Esempio, sprint di 30 m (vince il minore), da 10 a 11 anni: giallo da 5,9 s e verde da 5,4 s → 5,3 s è verde, 5,7 s è giallo e 6,1 s è rosso.',
    'Ejemplo:' => 'Esempio:',
    'Ejemplo: Escuela Completo (${n}) + Profesional (${n}) =' => 'Esempio: Scuola Completo (${n}) + Professionale (${n}) =',
    'Ejemplo: Profesional (${n}) + Escuela Completo (${n}) =' => 'Esempio: Professionale (${n}) + Scuola Completo (${n}) =',
    'Ejercer mis derechos' => 'Esercitare i miei diritti',
    'Ejercer mis derechos · Academia Prueba' => 'Esercitare i miei diritti · Academia Prueba',
    'Ejercer mis derechos · Escuela Demo TuAcademia' => 'Esercitare i miei diritti · Escuela Demo TuAcademia',
    'Ejercer mis derechos · Escuela Goleadores' => 'Esercitare i miei diritti · Escuela Goleadores',
    'Ejercer mis derechos · Federación Deportiva Demo' => 'Esercitare i miei diritti · Federación Deportiva Demo',
    'Ejercer mis derechos · Liga Barrial Norte' => 'Esercitare i miei diritti · Liga Barrial Norte',
    'Ejercer mis derechos · Liga Demo TuAcademia' => 'Esercitare i miei diritti · Liga Demo TuAcademia',
    'Ejercer mis derechos · Liga Referida Test' => 'Esercitare i miei diritti · Liga Referida Test',
    'Ejercicio de la biblioteca' => 'Esercizio della libreria',
    'Ejercicios' => 'Esercizi',
    'Ejercicios de la clase' => 'Esercizi della lezione',
    'El' => 'Il',
    'El archivo está vacío: debe tener la fila de títulos y al menos una fila con datos.' => 'Il file è vuoto: deve contenere la riga delle intestazioni e almeno una riga di dati.',
    'El archivo tiene más de' => 'Il file ha più di',
    'El arquero inicia con los defensores contra {n} o {n} delanteros que presionan; el objetivo es pasar la línea media con control.' => 'Il portiere inizia con i difensori contro {n} o {n} attaccanti che pressano; l\'obiettivo è superare la linea mediana con il controllo.',
    'El arquero inicia con los defensores contra {n} o {n} delanteros que presionan; el …' => 'Il portiere imposta con i difensori contro {n} o {n} attaccanti che pressano; il …',
    'El asistente' => 'L\'assistente',
    'El asistente nunca puede crear ni cambiar usuarios. Puede cambiar estos permisos cuando quiera; valen desde la siguiente página que abra.' => 'L\'assistente non può mai creare né modificare utenti. Può cambiare questi permessi quando vuole; valgono dalla pagina successiva che apre.',
    'El cliente le escribe aquí para confirmar o pagar.' => 'Il cliente Le scrive qui per confermare o pagare.',
    'El cobro con tarjeta se está terminando de conectar con Plux. Ya puede dejarlo configurado; el botón de pago aparecerá cuando esté listo.' => 'Il pagamento con carta è in fase di collegamento con Plux. Può già lasciarlo configurato; il pulsante di pagamento comparirà quando sarà pronto.',
    'El código' => 'Il codice',
    'El delegado sube la foto de su transferencia y el recibo sale al aprobarla.' => 'Il dirigente carica la foto del suo bonifico e la ricevuta viene emessa all\'approvazione.',
    'El enlace' => 'Il link',
    'El entrenador pasa desde afuera del área; el jugador controla orientado hacia el arco y remata en máximo 2 toques.' => 'L\'allenatore passa da fuori area; il giocatore controlla orientato verso la porta e tira in massimo 2 tocchi.',
    'El equipo' => 'La squadra',
    'El examen está cerrado. Ábralo de nuevo para corregir resultados.' => 'L\'esame è chiuso. Lo riapra per correggere i risultati.',
    'El examen está cerrado. Ábralo de nuevo para inscribir.' => 'L\'esame è chiuso. Lo riapra per iscrivere.',
    'El fixture completo de cada campeonato en PDF (con resultados o en blanco para llenar a mano) y el esquema de todo el torneo desde el primer día: grupos, jornadas y la llave de la fase final con los cruces (1° Grupo A vs 2° Grupo B), que se llenan solos con los clasificados.' => 'Il calendario completo di ogni campionato in PDF (con risultati o in bianco da compilare a mano) e lo schema di tutto il torneo fin dal primo giorno: gruppi, giornate e il tabellone della fase finale con gli accoppiamenti (1° Gruppo A vs 2° Gruppo B), che si riempiono da soli con i qualificati.',
    'El ganador de cada partido pasa solo a la siguiente ronda.' => 'Il vincitore di ogni partita passa automaticamente al turno successivo.',
    'El idioma con el que se abre su página para el público. Cada visitante (y cada usuario del panel) puede cambiarlo con el botón 🌐 de arriba.' => 'La lingua con cui si apre la sua pagina pubblica. Ogni visitatore (e ogni utente del pannello) può cambiarla con il pulsante 🌐 in alto.',
    'El informe de desarrollo reúne la asistencia, los gráficos de tests (comparados con su categoría), la evaluación técnica, las insignias, las metas y el comentario del profesor del trimestre. La familia también lo ve en su portal y lo puede guardar en PDF.' => 'Il rapporto di sviluppo riunisce le presenze, i grafici dei test (confrontati con la sua categoria), la valutazione tecnica, i badge, gli obiettivi e il commento dell\'istruttore del trimestre. Anche la famiglia lo vede nel proprio portale e può salvarlo in PDF.',
    'El informe del árbitro' => 'Il rapporto dell\'arbitro',
    'El jugador autorizó' => 'Il giocatore ha autorizzato',
    'El jugador no insultó al árbitro; pedimos revisar el video.' => 'Il giocatore non ha insultato l\'arbitro; chiediamo di rivedere il video.',
    'El lector' => 'Il lettore',
    'El pago con tarjeta no se completó.' => 'Il pagamento con carta non è stato completato.',
    'El perfil' => 'Il profilo',
    'El precio incluye' => 'Il prezzo include',
    'El profesor dio la clase' => 'L\'istruttore ha tenuto la lezione',
    'El profesor planifica las clases por adelantado con la biblioteca de ejercicios de la escuela; cada clase guarda ejercicios, minutos, intensidad, fotos y una nota para cada alumno, y los padres ven el diario de entrenamientos de su hijo.' => 'L\'istruttore pianifica le lezioni in anticipo con la biblioteca di esercizi della scuola; ogni lezione conserva esercizi, minuti, intensità, foto e una nota per ogni allievo, e i genitori vedono il diario degli allenamenti del proprio figlio.',
    'El profesor toma lista en segundos y anota el plan de la clase.' => 'L\'istruttore fa l\'appello in pochi secondi e annota il piano della lezione.',
    'El público reserva sus canchas por horas desde el celular y el cobro entra a finanzas.' => 'Il pubblico prenota i campi a ore dal cellulare e l\'incasso entra nelle finanze.',
    'El público vota desde la página de la liga (pestaña' => 'Il pubblico vota dalla pagina della lega (scheda',
    'El que corresponda por su edad' => 'Quello che spetta per la sua età',
    'El que está en curso' => 'Quello in corso',
    'El representante ve en su celular la asistencia, los pagos, las evaluaciones, la libreta y el carnet de sus hijos, y puede subir el comprobante de pago.' => 'Il genitore/tutore vede sul cellulare le presenze, i pagamenti, le valutazioni, la pagella e la tessera dei figli, e può caricare la ricevuta di pagamento.',
    'El semáforo de cada resultado sale solo:' => 'Il semaforo di ogni risultato appare da solo:',
    'El sistema completo para administrar tu liga de fútbol' => 'Il sistema completo per amministrare la tua lega di calcio',
    'El sistema completo para su escuela deportiva' => 'Il sistema completo per la Sua scuola sportiva',
    'El sistema le avisa por Telegram cuando alguien pide una demo, cuando a una demo le quedan {n} días (día {n}) y el día que vence (día {n}), con el mensaje de WhatsApp listo para enviar.' => 'Il sistema La avvisa via Telegram quando qualcuno richiede una demo, quando a una demo mancano {n} giorni (giorno {n}) e il giorno della scadenza (giorno {n}), con il messaggio WhatsApp pronto da inviare.',
    'El sistema pone a cada alumno en su categoría por edad (Sub-{n}, Sub-{n}, Sub-{n}…) o en grupos abiertos.' => 'Il sistema colloca ogni allievo nella sua categoria per età (Sub-{n}, Sub-{n}, Sub-{n}…) o in gruppi aperti.',
    'El sistema reparte horarios, canchas y árbitros sin choques, o lo hace usted a mano.' => 'Il sistema distribuisce orari, campi e arbitri senza sovrapposizioni, oppure lo fa Lei a mano.',
    'El sistema reparte los equipos al azar y puede generar el fixture de una vez.' => 'Il sistema distribuisce le squadre a sorte e può generare subito il calendario.',
    'El sistema reparte los partidos en las canchas y horarios que usted indique, sin que un equipo o un árbitro tenga dos partidos a la vez, alternando a los equipos entre horarios temprano y tarde y repartiendo los partidos entre los árbitros. Primero ve la propuesta y luego decide si la guarda.' => 'Il sistema distribuisce le partite nei campi e negli orari che Lei indica, senza che una squadra o un arbitro abbia due partite contemporanee, alternando le squadre tra orari mattutini e pomeridiani e ripartendo le partite tra gli arbitri. Prima vede la proposta e poi decide se salvarla.',
    'El sistema suma lo que se le debe a cada árbitro por los partidos jugados, según su función (central, asistente, cuarto). El valor por partido se pone en cada campeonato:' => 'Il sistema somma quanto spetta a ciascun arbitro per le partite giocate, in base al suo ruolo (centrale, assistente, quarto uomo). Il valore per partita si imposta in ogni campionato:',
    'El sistema ya está en inglés, francés, portugués e italiano: use el botón 🌐 de la barra de arriba. Elija el idioma de su página pública en Parámetros.' => 'Il sistema è già in inglese, francese, portoghese e italiano: usi il pulsante 🌐 della barra in alto. Scelga la lingua della Sua pagina pubblica in Impostazioni.',
    'El video pesa más de' => 'Il video pesa più di',
    'El vocal abre este enlace en su' => 'Il segnapunti apre questo link sul suo',
    'El vocal escanea el carnet y ve la foto:' => 'Il segnapunti scansiona la tessera e vede la foto:',
    'El vocal escanea el carnet y ve la foto: se acabaron las suplantaciones.' => 'Il segnapunti scansiona la tessera e vede la foto: finiscono le sostituzioni di persona.',
    'El vocal escanea este QR en la cancha. La hora en vivo demuestra que no es una captura de pantalla.' => 'Il segnapunti scansiona questo QR in campo. L\'ora in tempo reale dimostra che non è uno screenshot.',
    'El vocal marca desde el celular y los hinchas ven el marcador al instante en la página de la liga.' => 'Il segnapunti registra dal cellulare e i tifosi vedono il punteggio all\'istante nella pagina della lega.',
    'El vocal registra goles, tarjetas, cambios y reloj desde el celular (funciona aunque se caiga el internet). El público ve el marcador en vivo, se escanea el carnet QR y sale la hoja de vocalía en PDF.' => 'Il segnapunti registra gol, cartellini, sostituzioni e cronometro dal cellulare (funziona anche senza internet). Il pubblico vede il punteggio in diretta, si scansiona la tessera QR e si ottiene il referto in PDF.',
    'El árbitro' => 'L\'arbitro',
    'El árbitro todavía no ha llenado el informe.' => 'L\'arbitro non ha ancora compilato il rapporto.',
    'El último set (ej:' => 'L\'ultimo set (es.:',
    'El último set (ej: el {n}º) puede ser más corto.' => 'L\'ultimo set (es.: il {n}º) può essere più breve.',
