    'Elija' => 'Scelga',
    'Elija Taekwondo, Karate o Judo como deporte del grupo y tendrá: su propia lista de cinturones (kup/dan con puntas), categorías de peso oficiales, poomsae o kata de cada cinturón y exámenes de grado con cobro, acta y certificado con código QR. Está en Alumnos → Exámenes de grado.' => 'Scelga Taekwondo, Karate o Judo come sport del gruppo e avrà: il proprio elenco di cinture (kup/dan con punte), categorie di peso ufficiali, poomsae o kata di ogni cintura ed esami di grado con addebito, verbale e certificato con codice QR. Si trova in Allievi → Esami di grado.',
