    'Entra a su panel y ve solo sus pagos: quién pagó, cuánto, la comisión y lo que le transferimos.' => 'Accede al proprio pannello e vede solo i suoi pagamenti: chi ha pagato, quanto, la commissione e quanto Le abbiamo trasferito.',
