    'Entre a la página de cada escuela:' => 'Entri nella pagina di ogni scuola:',
    'Entre a la página de cada escuela: grupos, horarios e inscripción en línea.' => 'Entri nella pagina di ogni scuola: gruppi, orari e iscrizione online.',
    'Entre a la página de cada liga:' => 'Entri nella pagina di ogni lega:',
    'Entre a la página de cada liga: resultados en vivo, tabla, fixture y goleadores.' => 'Entri nella pagina di ogni lega: risultati in diretta, classifica, calendario e marcatori.',
    'Entre con un clic a cada panel, como si fuera el administrador, el árbitro, el delegado, el vocal o el jugador. Puede probar y guardar lo que quiera: los datos vuelven a estar como nuevos cada madrugada.' => 'Entri con un clic in ogni pannello, come se fosse l\'amministratore, l\'arbitro, il dirigente, il segnapunti o il giocatore. Può provare e salvare ciò che vuole: ogni notte i dati tornano come nuovi.',
    'Entregado por (delegado)' => 'Consegnato da (dirigente)',
    'Entregué conforme' => 'Consegnato conforme',
    'Entrena y se evalúa también en ese grupo, y cada mes se genera la mensualidad de ese grupo con {n} % de descuento.' => 'Si allena e viene valutato anche in quel gruppo, e ogni mese si genera la quota mensile di quel gruppo con {n} % di sconto.',
