    'Enviar avisos (programación, suspensiones, pagos pendientes, respuestas) por WhatsApp, Telegram o correo.' => 'Invia avvisi (programmazione, squalifiche, pagamenti in sospeso, risposte) via WhatsApp, Telegram o e-mail.',
