    'Esta es la lista que usa su escuela, en orden del primero al último. Puede cambiar el grado, el nombre, los colores, la punta y el forma de cada cinturón, o desmarcar los que no usa. El orden decide cuál es el «próximo cinturón» de cada alumno.' => 'Questo è l\'elenco che usa la sua scuola, in ordine dal primo all\'ultimo. Può cambiare il grado, il nome, i colori, la punta e la forma di ogni cintura, oppure deselezionare quelle che non usa. L\'ordine stabilisce qual è la «prossima cintura» di ogni allievo.',
    'Esta es la lista que usa su escuela, en orden del primero al último. Puede cambiar el grado, el nombre, los colores, la punta y el kata de cada cinturón, o desmarcar los que no usa. El orden decide cuál es el «próximo cinturón» de cada alumno.' => 'Questo è l\'elenco che usa la sua scuola, in ordine dal primo all\'ultimo. Può cambiare il grado, il nome, i colori, la punta e il kata di ogni cintura, oppure deselezionare quelle che non usa. L\'ordine stabilisce qual è la «prossima cintura» di ogni allievo.',
    'Esta es la lista que usa su escuela, en orden del primero al último. Puede cambiar el grado, el nombre, los colores, la punta y el poomsae de cada cinturón, o desmarcar los que no usa. El orden decide cuál es el «próximo cinturón» de cada alumno.' => 'Questo è l\'elenco che usa la sua scuola, in ordine dal primo all\'ultimo. Può cambiare il grado, il nome, i colori, la punta e il poomsae di ogni cintura, oppure deselezionare quelle che non usa. L\'ordine stabilisce qual è la «prossima cintura» di ogni allievo.',
