    'La comisión la asume su escuela o se le suma al que paga. Usted elige.' => 'La commissione è a carico della Sua scuola o viene aggiunta a chi paga. Lei sceglie.',
    'La comisión la asume su liga o se le suma al que paga. Usted elige.' => 'La commissione è a carico della Sua lega o viene aggiunta a chi paga. Lei sceglie.',
    'La comisión puede sumar más con una sanción manual.' => 'La commissione può aumentare con una sanzione manuale.',
    'La directiva o la comisión califica al árbitro después de cada partido (nota del {n} al {n}). Si es' => 'Il direttivo o la commissione valuta l\'arbitro dopo ogni partita (voto da {n} a {n}). Se è',
    'La edad de cada competidor es la que cumple en este año.' => 'L\'età di ogni concorrente è quella che compie in quest\'anno.',
    'La entrada se valida en la puerta con el lector de la liga.' => 'Il biglietto viene convalidato all\'ingresso con il lettore della lega.',
    'La escuela completa:' => 'La scuola completa:',
    'La escuela completa: profesores, evaluaciones, tienda y más' => 'La scuola completa: istruttori, valutazioni, negozio e altro',
    'La foto siempre se usa en el carnet y en la vocalía para verificar identidad. La cédula completa y los datos del representante nunca se publican.' => 'La foto viene sempre usata sulla tessera e nel referto per verificare l\'identità. Il documento d\'identità completo e i dati del genitore/tutore non vengono mai pubblicati.',
    'La inscripción en línea está' => 'L\'iscrizione online è',
    'La liga de demostración no se cuenta. "Ingreso mensual estimado" = último pago de cada liga pagando dividido para los meses que cubre.' => 'La lega demo non viene conteggiata. "Entrata mensile stimata" = ultimo pagamento di ogni lega pagante diviso per i mesi che copre.',
    'La maduración se calcula con la fórmula de Mirwald (talla, talla sentado, peso, edad y género). Dos chicos de la misma edad pueden estar hasta {n} años distintos en su desarrollo: esto ayuda a no descartar a los que maduran tarde y a cuidar la carga de los que están en pleno estirón.' => 'La maturazione si calcola con la formula di Mirwald (altezza, altezza da seduto, peso, età e genere). Due ragazzi della stessa età possono differire fino a {n} anni nel loro sviluppo: questo aiuta a non scartare chi matura tardi e a curare il carico di chi è in pieno scatto di crescita.',
    'La organización (declara tenerla)' => 'L\'organizzazione (dichiara di averla)',
    'La persona (por su cédula) queda' => 'La persona (tramite il documento d\'identità) risulta',
    'La pestaña' => 'La scheda',
    'La plantilla trae las columnas de ese deporte (pareja, peso, grado, vehículo, pruebas…) y en la hoja «Instrucciones» la lista de categorías o pruebas del campeonato.' => 'Il modello contiene le colonne di quello sport (compagno, peso, grado, veicolo, prove…) e, nel foglio «Istruzioni», l\'elenco delle categorie o prove del campionato.',
    'La prueba gratis automática está' => 'La prova gratuita automatica è',
    'La página de la liga se actualiza sola:' => 'La pagina della lega si aggiorna da sola:',
    'La página de la liga se actualiza sola: marcador, minuto y goleadores al instante.' => 'La pagina della lega si aggiorna da sola: punteggio, minuto e marcatori all\'istante.',
    'La página de la liga y su Resumen muestran los jugadores que cumplen años hoy (con su edad) y los equipos que se acercan a su aniversario (ponga la' => 'La pagina della lega e la sua Panoramica mostrano i giocatori che compiono gli anni oggi (con la loro età) e le squadre che si avvicinano al loro anniversario (inserisca la',
    'La página de su escuela con su propia dirección (www.suescuela.com) en vez de tuacademia.tukanec.com/su-escuela.' => 'La pagina della Sua scuola con il proprio indirizzo (www.suescuela.com) invece di tuacademia.tukanec.com/su-escuela.',
    'La página de verificación del carnet (a la que se llega escaneando el QR) muestra la foto y la cédula parcialmente oculta, solo para identificar al participante.' => 'La pagina di verifica della tessera (a cui si arriva scansionando il QR) mostra la foto e il documento d\'identità parzialmente oscurato, solo per identificare il partecipante.',
    'La tabla aparece cuando se juegue el primer partido pronosticado.' => 'La classifica compare quando si gioca la prima partita pronosticata.',
