    'La vocalía no deja marcar más presentes.' => 'Il referto non consente di segnare altri presenti.',
    'La vocalía sigue funcionando:' => 'Il referto continua a funzionare:',
    'La vocalía sigue funcionando: guarda los goles, tarjetas y presentes en el celular y los envía solos cuando vuelve la señal.' => 'Il referto continua a funzionare: salva gol, cartellini e presenti sul cellulare e li invia da solo quando torna il segnale.',
    'Lanzamiento de bala' => 'Lancio del peso',
    'Lanzamiento de bala · Damas {n} y {n} años' => 'Getto del peso · Donne {n} e {n} anni',
    'Lanzamiento de bala · Varones {n} y {n} años' => 'Getto del peso · Uomini {n} e {n} anni',
    'Lanzamiento de disco' => 'Lancio del disco',
    'Lanzamiento de jabalina' => 'Lancio del giavellotto',
    'Las canchas se administran en' => 'I campi si gestiscono in',
    'Las demás medidas (cadera, brazo, muslo, % grasa, envergadura) se registran en la ficha de cada alumno.' => 'Le altre misure (fianchi, braccio, coscia, % massa grassa, apertura alare) si registrano nella scheda di ogni allievo.',
    'Las facturas electrónicas' => 'Le fatture elettroniche',
    'Las familias suben aquí la foto de su transferencia desde su portal. Revise que el dinero llegó y apruébelo: se emite el recibo.' => 'Le famiglie caricano qui la foto del loro bonifico dal proprio portale. Verifichi che il denaro sia arrivato e lo approvi: viene emessa la ricevuta.',
    'Las fotos no van en el Excel: se suben después en cada equipo, o las sube cada delegado.' => 'Le foto non vanno nel file Excel: si caricano poi in ogni squadra, oppure le carica ogni dirigente.',
    'Las fotos no van en el Excel: se suben después en la ficha de cada persona. Máximo' => 'Le foto non vanno nel file Excel: si caricano poi nella scheda di ogni persona. Massimo',
    'Las fotos no van en el Excel: se suben después en la ficha de cada persona. Máximo {n} filas por archivo. También acepta archivos CSV.' => 'Le foto non vanno nell\'Excel: si caricano dopo nella scheda di ogni persona. Massimo {n} righe per file. Accetta anche file CSV.',
    'Las fotos y los comprobantes no van en el Excel. Para subir datos desde Excel use' => 'Le foto e le ricevute non vanno nel file Excel. Per caricare dati da Excel usi',
    'Las ligas y escuelas le pagan su suscripción con tarjeta, y sus equipos y familias les pagan a ellas con TuAcademia de intermediario. Reporte y transferencias en' => 'Le leghe e le scuole Le pagano l\'abbonamento con carta, e le loro squadre e famiglie pagano loro con TuAcademia come intermediario. Report e bonifici in',
    'Las medidas se toman en' => 'Le misure si prendono in',
    'Las mensualidades se generan solas' => 'Le quote mensili si generano da sole',
    'Las mensualidades se generan solas, con su fecha de vencimiento, becas y descuento por hermanos.' => 'Le quote mensili si generano da sole, con la data di scadenza, borse di studio e sconto fratelli.',
    'Las opciones son los goles de esa jornada (en básquet, los triples).' => 'Le opzioni sono i gol di quella giornata (nel basket, le triple).',
    'Las opciones son los jugadores presentes (si la vocalía los marcó) o las dos plantillas.' => 'Le opzioni sono i giocatori presenti (se il referto li ha segnati) o le due rose.',
    'Las reglas vienen llenas con los valores por defecto de la liga. Cámbielas solo si este campeonato es distinto (otra modalidad, otra duración, otro número de árbitros, etc.).' => 'Le regole vengono precompilate con i valori predefiniti della lega. Le modifichi solo se questo campionato è diverso (altra modalità, altra durata, altro numero di arbitri, ecc.).',
    'Le ayudamos a cargar sus alumnos y grupos' => 'La aiutiamo a caricare i Suoi allievi e gruppi',
    'Le ayudamos a cargar sus equipos y su primer campeonato' => 'La aiutiamo a caricare le Sue squadre e il Suo primo campionato',
    'Le faltan' => 'Mancano',
    'Le llega un aviso al celular con cada gol, el resultado final y los horarios de Atlético Chimborazo (Liga Demo TuAcademia). Gratis, sin Telegram ni WhatsApp.' => 'Riceve un avviso sul cellulare a ogni gol, con il risultato finale e gli orari di Atlético Chimborazo (Liga Demo TuAcademia). Gratis, senza Telegram né WhatsApp.',
    'Le llega un aviso al celular con cada gol, el resultado final y los horarios de Atlético Chimborazo. Gratis, sin Telegram ni WhatsApp.' => 'Riceve un avviso sul cellulare a ogni gol, con il risultato finale e gli orari di Atlético Chimborazo. Gratis, senza Telegram né WhatsApp.',
    'Le llega un aviso al celular con cada gol, el resultado final y los horarios de Deportivo Los Andes (Liga Demo TuAcademia). Gratis, sin Telegram ni WhatsApp.' => 'Riceve un avviso sul cellulare a ogni gol, con il risultato finale e gli orari di Deportivo Los Andes (Liga Demo TuAcademia). Gratis, senza Telegram né WhatsApp.',
