    'Le llega un aviso al celular con cada gol, el resultado final y los horarios de Estrella del Sur. Gratis, sin Telegram ni WhatsApp.' => 'Riceve un avviso sul cellulare a ogni gol, con il risultato finale e gli orari di Estrella del Sur. Gratis, senza Telegram né WhatsApp.',
    'Le llega un aviso al celular con cada gol, el resultado final y los horarios de Leones. Gratis, sin Telegram ni WhatsApp.' => 'Riceve un avviso sul cellulare a ogni gol, con il risultato finale e gli orari di Leones. Gratis, senza Telegram né WhatsApp.',
    'Le llega un aviso al celular con cada gol, el resultado final y los horarios de Pumas. Gratis, sin Telegram ni WhatsApp.' => 'Le arriva un avviso sul cellulare con ogni gol, il risultato finale e gli orari dei Pumas. Gratis, senza Telegram né WhatsApp.',
    'Le llega un aviso al celular con cada gol, el resultado final y los horarios de Real Cotopaxi. Gratis, sin Telegram ni WhatsApp.' => 'Riceve un avviso sul cellulare a ogni gol, con il risultato finale e gli orari di Real Cotopaxi. Gratis, senza Telegram né WhatsApp.',
    'Le llega un aviso al celular con cada gol, el resultado final y los horarios de Tigres. Gratis, sin Telegram ni WhatsApp.' => 'Le arriva un avviso sul cellulare con ogni gol, il risultato finale e gli orari dei Tigres. Gratis, senza Telegram né WhatsApp.',
    'Le llega un aviso al celular con cada gol, el resultado final y los horarios de {s}.' => 'Riceve un avviso sul cellulare a ogni gol, con il risultato finale e gli orari di {s}.',
    'Le llega un aviso al celular con cada gol, el resultado final y los horarios de Águilas FC. Gratis, sin Telegram ni WhatsApp.' => 'Riceve un avviso sul cellulare a ogni gol, con il risultato finale e gli orari di Águilas FC. Gratis, senza Telegram né WhatsApp.',
    'Le llegan avisos de sus goles, resultados y horarios. Para seguir otro equipo, ábralo en la página de su liga y toque' => 'Le arrivano avvisi con i gol, i risultati e gli orari della sua squadra. Per seguire un\'altra squadra, la apra nella pagina della sua lega e tocchi',
    'Le mostramos el sistema con un asesor y le creamos su acceso de prueba para su escuela, con sus propios datos.' => 'Le mostriamo il sistema con un consulente e Le creiamo il Suo accesso di prova per la Sua scuola, con i Suoi dati.',
    'Le mostramos el sistema con un asesor y le creamos su acceso de prueba para su liga, con sus propios datos.' => 'Le mostriamo il sistema con un consulente e Le creiamo il Suo accesso di prova per la Sua lega, con i Suoi dati.',
