    'Llegó tarde' => 'È arrivato in ritardo',
    'Llene este formulario y la liga queda funcionando con su administrador, su página pública y (si quiere) su primer campeonato. No hay que copiar archivos ni tocar el servidor.' => 'Compili questo modulo e la lega è subito operativa con il suo amministratore, la sua pagina pubblica e (se vuole) il suo primo campionato. Non occorre copiare file né toccare il server.',
    'Lo asume la liga (el que paga ve el valor exacto; a usted le llega el valor menos la comisión)' => 'A carico della lega (chi paga vede l\'importo esatto; a Lei arriva l\'importo meno la commissione)',
    'Lo básico (Equipos y jugadores con foto, Sorteo y fixture automático (todos contra todos, grupos, ida y vuelta), Llaves eliminatorias automáticas, Tabla de posiciones, goleadores y tarjetas, Suspensiones automáticas y sanciones…) viene en todos los planes. Marque los módulos que trae este plan:' => 'Le basi (Squadre e giocatori con foto, Sorteggio e calendario automatico (tutti contro tutti, gironi, andata e ritorno), Tabelloni a eliminazione diretta automatici, Classifica, marcatori e cartellini, Squalifiche automatiche e sanzioni…) sono incluse in tutti i piani. Selezioni i moduli inclusi in questo piano:',
    'Lo más importante de hoy' => 'Le cose più importanti di oggi',
    'Lo necesito pronto' => 'Mi serve presto',
    'Lo nuevo de cada versión' => 'Novità di ogni versione',
