    'Lo que cargó' => 'Quanto ha addebitato',
    'Lo que entrenó en cada clase, la nota del profesor y las fotos. Los padres lo ven igual en su portal.' => 'Ciò che ha fatto in ogni lezione, la nota dell\'istruttore e le foto. I genitori lo vedono allo stesso modo nel loro portale.',
    'Lo que las ligas le pagan a TuAcademia se envía a Plux como valor con IVA incluido.' => 'Quanto le leghe pagano a TuAcademia viene inviato a Plux come importo IVA inclusa.',
