    'Los' => 'I',
    'Los Andes · Ruta' => 'Los Andes · Strada',
    'Los XML que le llegan al correo con cada factura. Puede elegir varios a la vez o un' => 'Gli XML che Le arrivano per e-mail con ogni fattura. Può sceglierne diversi alla volta o un',
    'Los avisos NO le están llegando:' => 'Gli avvisi NON Le stanno arrivando:',
    'Los avisos por Telegram no le están llegando' => 'Gli avvisi Telegram non Le stanno arrivando',
    'Los celulares solo los ve la liga (para entregar premios). No se publican.' => 'I cellulari li vede solo la lega (per consegnare i premi). Non vengono pubblicati.',
    'Los cobros de' => 'Gli incassi di',
    'Los competidores se inscriben solos (y pueden pagar con tarjeta). Además: imágenes para redes, hojas para imprimir, resultados en vivo y copiar para la nueva temporada.' => 'I concorrenti si iscrivono da soli (e possono pagare con carta). Inoltre: immagini per i social, fogli da stampare, risultati in diretta e copia per la nuova stagione.',
    'Los comprobantes de' => 'Le ricevute di pagamento di',
    'Los datos' => 'I dati',
    'Los datos de menores de {n} años se tratan con especial cuidado: su inscripción requiere la autorización y los datos del representante legal, y su foto no se publica sin permiso expreso.' => 'I dati dei minori di {n} anni vengono trattati con particolare cura: la loro iscrizione richiede l\'autorizzazione e i dati del rappresentante legale, e la loro foto non viene pubblicata senza esplicito consenso.',
    'Los datos se guardan en' => 'I dati sono conservati su',
    'Los delegados envían desde su portal la foto de su transferencia o depósito. Revise que el dinero llegó a la cuenta y apruébelo: el pago y el recibo se registran solos. Los datos de la cuenta para pagar se escriben en' => 'I dirigenti inviano dal loro portale la foto del bonifico o del versamento. Verifichi che il denaro sia arrivato sul conto e lo approvi: il pagamento e la ricevuta si registrano da soli. I dati del conto per il pagamento si inseriscono in',
    'Los delegados los ven al enviar el comprobante de su transferencia.' => 'I dirigenti li vedono quando inviano la ricevuta del loro bonifico.',
    'Los delegados piden desde su portal:' => 'I dirigenti richiedono dal proprio portale:',
    'Los delegados pueden inscribir jugadores hasta' => 'I dirigenti possono iscrivere giocatori fino al',
    'Los delegados pueden pedir pases en línea' => 'I dirigenti possono richiedere trasferimenti online',
    'Los ejercicios de la escuela. El profesor los elige al planificar cada clase y los padres ven en el diario qué ejercicios hizo su hijo.' => 'Gli esercizi della scuola. L\'istruttore li sceglie quando pianifica ogni lezione e i genitori vedono nel diario quali esercizi ha fatto il figlio.',
    'Los equipos no tienen jugadores registrados.' => 'Le squadre non hanno giocatori registrati.',
    'Los equipos se inscriben por internet y cada delegado registra a sus jugadores.' => 'Le squadre si iscrivono via internet e ogni dirigente registra i propri giocatori.',
    'Los equipos se inscriben por internet; cada delegado inscribe a sus jugadores, pide pases, reprogramaciones y apelaciones y ve su estado de cuenta.' => 'Le squadre si iscrivono via internet; ogni dirigente iscrive i propri giocatori, richiede trasferimenti, riprogrammazioni e ricorsi e vede il proprio estratto conto.',
    'Los equipos y los padres pagan con tarjeta desde su celular, el recibo sale solo y usted ve cada pago en su reporte.' => 'Le squadre e i genitori pagano con carta dal cellulare, la ricevuta viene emessa da sola e Lei vede ogni pagamento nel suo report.',
    'Los hinchas adivinan los resultados de los próximos partidos desde la página de la liga y suman puntos.' => 'I tifosi indovinano i risultati delle prossime partite dalla pagina della lega e accumulano punti.',
    'Los hinchas pronostican los resultados gratis y compiten en una tabla. Sin apuestas.' => 'I tifosi pronosticano i risultati gratuitamente e competono in una classifica. Senza scommesse.',
    'Los hinchas reciben en el celular cada gol, el resultado y los horarios de su equipo.' => 'I tifosi ricevono sul cellulare ogni gol, il risultato e gli orari della loro squadra.',
    'Los impuestos solo se muestran desglosados en el reporte; consulte con su contador si su liga debe cobrarlos.' => 'Le imposte vengono mostrate in dettaglio solo nel report; si consulti con il Suo commercialista per sapere se la Sua lega deve riscuoterle.',
    'Los lugares donde entrenan (nombre y dirección).' => 'I luoghi dove si allenano (nome e indirizzo).',
    'Los límites y módulos se aplican solos a cada liga o escuela según su plan (en la prueba gratis tienen todo). {n} = sin límite. Un precio en {n} = ese período no se ofrece. En Ligas → Editar puede regalar módulos a una liga.' => 'I limiti e i moduli si applicano da soli a ogni lega o scuola secondo il suo piano (nella prova gratuita hanno tutto). {n} = illimitato. Un prezzo in {n} = quel periodo non è offerto. In Leghe → Modifica può regalare moduli a una lega.',
    'Los manuales de ligas y de escuelas ya están en español, inglés, francés, portugués e italiano, con todo lo nuevo. Elija el idioma con el botón 🌐.' => 'I manuali di leghe e scuole sono già in spagnolo, inglese, francese, portoghese e italiano, con tutte le novità. Scelga la lingua con il pulsante 🌐.',
    'Los marcadores en vivo se actualizan solos cada {n} segundos.' => 'I punteggi in diretta si aggiornano da soli ogni {n} secondi.',
    'Los módulos, uno por uno' => 'I moduli, uno per uno',
    'Los padres inscriben a sus hijos desde la página de la escuela.' => 'I genitori iscrivono i propri figli dalla pagina della scuola.',
    'Los padres inscriben a sus hijos por internet y ven asistencia, pagos, recibos, evaluaciones y libreta desde el celular.' => 'I genitori iscrivono i propri figli via internet e vedono presenze, pagamenti, ricevute, valutazioni e pagella dal cellulare.',
    'Los padres llenan la ficha desde la página de la escuela. Llega a' => 'I genitori compilano la scheda dalla pagina della scuola. Arriva a',
    'Los padres pagan con tarjeta desde su celular y el pago se aplica solo.' => 'I genitori pagano con carta dal cellulare e il pagamento viene applicato da solo.',
    'Los padres pagan con tarjeta desde su celular, el recibo sale solo y usted ve cada pago en su reporte.' => 'I genitori pagano con carta dal cellulare, la ricevuta viene emessa da sola e Lei vede ogni pagamento nel suo report.',
    'Los padres pagan con tarjeta; el recibo sale solo. TuAcademia le transfiere lo cobrado menos la comisión de la tarjeta (Tarjeta de crédito {n}% + IVA' => 'I genitori pagano con carta; la ricevuta viene emessa da sola. TuAcademia Le trasferisce quanto incassato meno la commissione della carta (Carta di credito {n}% + IVA',
    'Los padres pagan con tarjeta; el recibo sale solo. TuAcademia le transfiere lo cobrado menos la comisión de la tarjeta (Tarjeta de crédito {n}% + IVA · Tarjeta de débito {n}% + IVA · Gestión administrativa de TuAcademia {n}%). Usted elige si la comisión la asume su organización o el que paga.' => 'I genitori pagano con carta; la ricevuta viene emessa da sola. TuAcademia Le trasferisce quanto incassato meno la commissione della carta (Carta di credito {n}% + IVA · Carta di debito {n}% + IVA · Gestione amministrativa di TuAcademia {n}%). Lei sceglie se la commissione è a carico della Sua organizzazione o di chi paga.',
    'Los padres pagan las mensualidades con tarjeta de crédito o débito desde su celular; el recibo sale solo y usted ve cada pago en su reporte.' => 'I genitori pagano le quote mensili con carta di credito o di debito dal cellulare; la ricevuta viene emessa da sola e Lei vede ogni pagamento nel suo report.',
    'Los padres pueden ver las fotos' => 'I genitori possono vedere le foto',
    'Los padres ven el plan' => 'I genitori vedono il piano',
    'Los pases en línea solo se piden mientras la inscripción de jugadores está' => 'I trasferimenti online si richiedono solo mentre l\'iscrizione dei giocatori è',
    'Los pilotos con «categoría automática» entran a la primera que cumpla su cilindrada y su motor (atmosférico o turbo). Los turbo van a la categoría turbo aunque su cilindrada sea baja.' => 'I piloti con «categoria automatica» entrano nella prima che soddisfa la loro cilindrata e il loro motore (aspirato o turbo). I turbo vanno nella categoria turbo anche se la cilindrata è bassa.',
    'Los que carga el vocal en vivo aparecen aquí automáticamente.' => 'Quelli che il segnapunti carica in diretta compaiono qui automaticamente.',
    'Los ven las familias en su portal y en los recibos.' => 'Le vedono le famiglie nel loro portale e nelle ricevute.',
    'Luciana Pérez Ortiz (+{n}% en promedio)' => 'Luciana Pérez Ortiz (+{n}% in media)',
    'Luego el panel de la liga queda en solo lectura (la página pública sigue visible).' => 'Poi il pannello della lega resta in sola lettura (la pagina pubblica rimane visibile).',
