    'Mientras la persona participe en la escuela y luego el tiempo necesario para conservar el historial deportivo (campeones, estadísticas) y cumplir obligaciones legales (por ejemplo, contables y tributarias). Se puede pedir la eliminación en cualquier momento (punto {n}): en ese caso los datos personales se borran y solo quedan las estadísticas sin nombre.' => 'Finché la persona partecipa alla scuola e poi per il tempo necessario a conservare lo storico sportivo (campioni, statistiche) e adempiere agli obblighi di legge (ad esempio contabili e fiscali). La cancellazione può essere richiesta in qualsiasi momento (punto {n}): in tal caso i dati personali vengono cancellati e restano solo le statistiche anonime.',
    'Mientras la persona participe en la liga y luego el tiempo necesario para conservar el historial deportivo (campeones, estadísticas) y cumplir obligaciones legales (por ejemplo, contables y tributarias). Se puede pedir la eliminación en cualquier momento (punto {n}): en ese caso los datos personales se borran y solo quedan las estadísticas sin nombre.' => 'Finché la persona partecipa alla lega e poi per il tempo necessario a conservare lo storico sportivo (campioni, statistiche) e adempiere agli obblighi di legge (ad esempio contabili e fiscali). La cancellazione può essere richiesta in qualsiasi momento (punto {n}): in tal caso i dati personali vengono cancellati e restano solo le statistiche anonime.',
    'Mientras la persona participe en la organización y luego el tiempo necesario para conservar el historial deportivo (campeones, estadísticas) y cumplir obligaciones legales (por ejemplo, contables y tributarias). Se puede pedir la eliminación en cualquier momento (punto {n}): en ese caso los datos personales se borran y solo quedan las estadísticas sin nombre.' => 'Finché la persona partecipa all\'organizzazione e poi per il tempo necessario a conservare lo storico sportivo (campioni, statistiche) e adempiere agli obblighi di legge (ad esempio contabili e fiscali). La cancellazione può essere richiesta in qualsiasi momento (punto {n}): in tal caso i dati personali vengono cancellati e restano solo le statistiche anonime.',
    'Mientras más afuera, mejor que el resto de su categoría en la escuela.' => 'Più è all\'esterno, migliore rispetto al resto della sua categoria nella scuola.',
