    'Para campeonatos cortos (relámpago, de verano, de barrio): un solo torneo de hasta 20 equipos durante 3 meses, con casi todos los módulos (el fixture para imprimir y el esquema del campeonato son del plan Profesional).' => 'Per campionati brevi (lampo, estivi, di quartiere): un solo torneo fino a 20 squadre per 3 mesi, con quasi tutti i moduli (il calendario da stampare e lo schema del campionato sono del piano Professionale).',
    'Para campeonatos cortos (relámpago, de verano, de barrio): un solo torneo de hasta {n} equipos durante {n} meses, con todos los módulos.' => 'Per campionati brevi (lampo, estivi, di quartiere): un solo torneo fino a {n} squadre per {n} mesi, con tutti i moduli.',
    'Para clubes y academias que compiten con sus categorías (Sub-{n} a Sub-{n}). Agrega:' => 'Per club e accademie che competono con le loro categorie (da Sub-{n} a Sub-{n}). Aggiunge:',
    'Para clubes y academias:' => 'Per club e accademie:',
    'Para clubes y academias: partidos con convocatoria y minutos jugados, notas del cuerpo técnico por área, valoración del jugador, seguimiento escolar, maduración y pico de crecimiento, y lesiones con fases de regreso. Se activa en Parámetros.' => 'Per club e accademie: partite con convocazione e minuti giocati, note dello staff tecnico per area, valutazione del giocatore, monitoraggio scolastico, maturazione e picco di crescita, e infortuni con fasi di rientro. Si attiva in Impostazioni.',
