    'Se cambia en los datos del profesor.' => 'Si cambia nei dati dell\'istruttore.',
    'Se carga a los dos equipos al jugarse el partido. En W.O. paga el doble el que no se presentó.' => 'Viene addebitato a entrambe le squadre quando si gioca la partita. In caso di a tavolino paga il doppio la squadra che non si è presentata.',
