    'Se carga sola a cada equipo inscrito. {n} = no se cobra.' => 'Viene addebitata automaticamente a ogni squadra iscritta. {n} = non si incassa.',
    'Se cargó el derecho a examen (${n}) a {n} alumno(s). Ya aparece en Pagos y en el portal de los padres.' => 'La quota d\'esame (${n}) è stata addebitata a {n} allievo/i. Compare già in Pagamenti e nel portale dei genitori.',
