    'Se compara con su última medición.' => 'Viene confrontata con l\'ultima misurazione.',
    'Se copian las reglas de juego, puntos, tarjetas, árbitros, dinero y categoría. No se copian partidos, resultados, sanciones ni el campeón. Las fechas de inscripción en línea quedan cerradas hasta que las ponga.' => 'Vengono copiate le regole di gioco, punti, cartellini, arbitri, denaro e categoria. Non vengono copiati partite, risultati, sanzioni né il campione. Le date di iscrizione online restano chiuse finché non le imposta.',
    'Se crea solo si lo deja vacío' => 'Viene creato da solo se lo lascia vuoto',
    'Se crean solas cada mes; use esto solo para adelantar el mes siguiente.' => 'Si creano da sole ogni mese; usi questa opzione solo per anticipare il mese successivo.',
    'Se crean solas con los datos del sistema, el logo y el color de la liga y el patrocinador (se configura en' => 'Si creano automaticamente con i dati del sistema, il logo e il colore della lega e dello sponsor (si configura in',
