    'Se edita en la pestaña Datos → Ficha médica.' => 'Si modifica nella scheda Dati → Scheda medica.',
    'Se generan solas cada mes, con becas y descuento por hermanos. Semáforo de quién está al día.' => 'Si generano automaticamente ogni mese, con borse di studio e sconto fratelli. Semaforo di chi è in regola.',
