    'Sus datos' => 'I suoi dati',
    'Sus equipos pagan con tarjeta de crédito o débito desde su celular. TuAcademia recibe el dinero por medio de Plux, aplica el pago y emite el recibo al instante, y le transfiere lo cobrado a su cuenta. Costo: Tarjeta de crédito {n}% + IVA' => 'Le sue squadre pagano con carta di credito o debito dal cellulare. TuAcademia riceve il denaro tramite Plux, applica il pagamento ed emette subito la ricevuta, e Le trasferisce quanto incassato sul suo conto. Costo: Carta di credito {n}% + IVA',
    'Sus equipos pagan con tarjeta de crédito o débito desde su celular. TuAcademia recibe el dinero por medio de Plux, aplica el pago y emite el recibo al instante, y le transfiere lo cobrado a su cuenta. Costo: Tarjeta de crédito {n}% + IVA · Tarjeta de débito {n}% + IVA · Gestión administrativa de TuAcademia {n}%.' => 'Le sue squadre pagano con carta di credito o debito dal cellulare. TuAcademia riceve il denaro tramite Plux, applica il pagamento ed emette subito la ricevuta, e Le trasferisce quanto incassato sul suo conto. Costo: Carta di credito {n}% + IVA · Carta di debito {n}% + IVA · Gestione amministrativa di TuAcademia {n}%.',
    'Sus equipos pagan con tarjeta de crédito o débito; el recibo sale solo y usted recibe la transferencia en su cuenta. Costo por transacción: Tarjeta de crédito {n}% + IVA' => 'Le sue squadre pagano con carta di credito o debito; la ricevuta esce da sola e Lei riceve il bonifico sul suo conto. Costo per transazione: Carta di credito {n}% + IVA',
    'Sus equipos pagan con tarjeta de crédito o débito; el recibo sale solo y usted recibe la transferencia en su cuenta. Costo por transacción: Tarjeta de crédito {n}% + IVA · Tarjeta de débito {n}% + IVA · Gestión administrativa de TuAcademia {n}%. Usted elige si la comisión la asume su organización o el que paga.' => 'Le sue squadre pagano con carta di credito o debito; la ricevuta esce da sola e Lei riceve il bonifico sul suo conto. Costo per transazione: Carta di credito {n}% + IVA · Carta di debito {n}% + IVA · Gestione amministrativa di TuAcademia {n}%. Lei sceglie se la commissione è a carico della sua organizzazione o di chi paga.',
    'Sus equipos pagan con tarjeta; el recibo sale solo. TuAcademia le transfiere lo cobrado menos la comisión de la tarjeta (Tarjeta de crédito {n}% + IVA' => 'Le sue squadre pagano con carta; la ricevuta esce da sola. TuAcademia Le trasferisce quanto incassato meno la commissione della carta (Carta di credito {n}% + IVA',
    'Sus equipos pagan con tarjeta; el recibo sale solo. TuAcademia le transfiere lo cobrado menos la comisión de la tarjeta (Tarjeta de crédito {n}% + IVA · Tarjeta de débito {n}% + IVA · Gestión administrativa de TuAcademia {n}%). Usted elige si la comisión la asume su organización o el que paga.' => 'Le sue squadre pagano con carta; la ricevuta esce da sola. TuAcademia Le trasferisce quanto incassato meno la commissione della carta (Carta di credito {n}% + IVA · Carta di debito {n}% + IVA · Gestione amministrativa di TuAcademia {n}%). Lei sceglie se la commissione è a carico della sua organizzazione o di chi paga.',
    'Sus equipos pagan inscripciones, arbitrajes y multas con' => 'Le sue squadre pagano iscrizioni, arbitraggi e multe con',
    'Sus equipos y familias le pagan con tarjeta de crédito o débito desde su celular; el sistema aplica el pago, emite el recibo y usted ve todo en su reporte de pagos.' => 'Le sue squadre e famiglie La pagano con carta di credito o debito dal cellulare; il sistema applica il pagamento, emette la ricevuta e Lei vede tutto nel suo report dei pagamenti.',
    'Sus familias pagan con tarjeta de crédito o débito; el recibo sale solo y usted recibe la transferencia en su cuenta. Costo por transacción: Tarjeta de crédito {n}% + IVA' => 'Le sue famiglie pagano con carta di credito o debito; la ricevuta esce da sola e Lei riceve il bonifico sul suo conto. Costo per transazione: Carta di credito {n}% + IVA',
    'Sus familias pagan con tarjeta de crédito o débito; el recibo sale solo y usted recibe la transferencia en su cuenta. Costo por transacción: Tarjeta de crédito {n}% + IVA · Tarjeta de débito {n}% + IVA · Gestión administrativa de TuAcademia {n}%. Usted elige si la comisión la asume su organización o el que paga.' => 'Le sue famiglie pagano con carta di credito o debito; la ricevuta esce da sola e Lei riceve il bonifico sul suo conto. Costo per transazione: Carta di credito {n}% + IVA · Carta di debito {n}% + IVA · Gestione amministrativa di TuAcademia {n}%. Lei sceglie se la commissione è a carico della sua organizzazione o di chi paga.',
    'Sus familias pagan las mensualidades con' => 'Le sue famiglie pagano le quote mensili con',
    'Sus goles y tarjetas anteriores quedan con su equipo anterior. El sistema revisa el cupo y la categoría del equipo que lo recibe.' => 'I suoi gol e cartellini precedenti restano con la sua squadra precedente. Il sistema verifica il posto disponibile e la categoria della squadra che lo riceve.',
