    'Sí, cuando quiera, desde "Mi plan" en su panel. Los módulos nuevos se activan al instante y no pierde ningún dato.' => 'Sì, quando vuole, da "Il mio piano" nel suo pannello. I nuovi moduli si attivano subito e non perde alcun dato.',
