    'Sí: cada liga y cada campeonato tienen su dirección corta ({n}:{n}/su-liga/apertura) y, pagando el plan Profesional por {n} año, le damos un dominio propio (www.suliga.com).' => 'Sì: ogni lega e ogni campionato hanno il proprio indirizzo breve ({n}:{n}/su-liga/apertura) e, pagando il piano Professionale per {n} anno, Le diamo un dominio proprio (www.suliga.com).',
    'Sí: fútbol {n}, {n}, {n}, {n}, {n}, {n} o personalizado, indor, ecuavóley por sets y básquet. Cada campeonato define sus jugadores, tiempos, árbitros y reglas.' => 'Sì: calcio a {n}, {n}, {n}, {n}, {n}, {n} o personalizzato, calcio a 5, ecuavóley a set e basket. Ogni campionato definisce giocatori, tempi, arbitri e regole.',
    'Sí: su escuela tiene su dirección corta ({n}:{n}/su-escuela) y, pagando el plan Escuela Completo por {n} año, le damos un dominio propio (www.suescuela.com).' => 'Sì: la sua scuola ha il proprio indirizzo breve ({n}:{n}/su-escuela) e, pagando il piano Scuola Completo per {n} anno, Le diamo un dominio proprio (www.suescuela.com).',
