    'Varias ligas y escuelas de cualquier deporte bajo un mismo paraguas: resumen, partidos de la semana, sanciones federativas que se respetan en todas las ligas y campeonatos inter-ligas. Su liga puede afiliarse en Parámetros → Federación.' => 'Varie leghe e scuole di qualsiasi sport sotto un unico ombrello: riepilogo, partite della settimana, sanzioni federali rispettate in tutte le leghe e campionati inter-leghe. La Sua lega può affiliarsi in Impostazioni → Federazione.',
