    'Venda espacios a empresas del barrio:' => 'Venda spazi alle aziende del quartiere:',
    'Venda espacios a empresas del barrio: su banner sale en la página pública de la liga, en los partidos ("Partido presentado por…"), en las imágenes para redes y en los carnets. El sistema cuenta cuántas veces se mostró su marca y cuántos clics recibió: imprima el' => 'Venda spazi alle aziende del quartiere: il loro banner compare nella pagina pubblica della lega, nelle partite ("Partita presentata da…"), nelle immagini per i social e nelle tessere. Il sistema conta quante volte è stato mostrato il marchio e quanti clic ha ricevuto: stampi il',
    'Venda las entradas de sus partidos por internet (tarjeta o transferencia), en taquilla y cortesías, con parqueadero opcional. Cada entrada tiene su QR y en la puerta se valida con el celular, aunque no haya internet.' => 'Venda i biglietti delle sue partite su internet (carta o bonifico), al botteghino e come omaggi, con parcheggio facoltativo. Ogni biglietto ha il suo QR e all\'ingresso si convalida con il cellulare, anche senza internet.',
    'Venda por adelantado las entradas de sus partidos, también a los hinchas. Cada entrada tiene su QR y en la puerta se valida con el celular. Si no marca la casilla, no aparece nada de esto.' => 'Venda in anticipo i biglietti delle sue partite, anche ai tifosi. Ogni biglietto ha il suo QR e all\'ingresso si convalida con il cellulare. Se non spunta la casella, non compare nulla di tutto questo.',
