    'Suba la foto o captura' => 'Carica la foto o lo screenshot',
    'del comprobante y envíe. Lo revisamos y su cuenta queda activa el mismo día, con todo lo que ya cargó.' => 'della ricevuta e invia. La verifichiamo e il tuo account viene attivato lo stesso giorno, con tutto ciò che hai già caricato.',
    'del comprobante y envíe. Lo revisamos y su cuenta queda activa el mismo día.' => 'della ricevuta e invia. La verifichiamo e il tuo account viene attivato lo stesso giorno.',
    'Plan y tiempo' => 'Piano e periodo',
    'Foto o captura del comprobante' => 'Foto o screenshot della ricevuta',
    'Nota (opcional)' => 'Nota (facoltativa)',
    'N° de transferencia, banco, nombre de quien pagó, RUC para la factura…' => 'N. bonifico, banca, nome di chi ha pagato, partita IVA per la fattura…',
    'Comprobantes enviados' => 'Ricevute inviate',
    'Aprobada' => 'Approvata',
    'Rechazada' => 'Rifiutata',
    'Su comprobante está en revisión' => 'La tua ricevuta è in verifica',
    '(plan {s}, {s} mes(es), ${s}, enviado el {s}). Le avisamos apenas lo aprobemos, normalmente el mismo día.' => '(piano {s}, {s} mese/i, ${s}, inviata il {s}). Ti avviseremo appena approvata, di solito lo stesso giorno.',
    'Si es urgente,' => 'Se è urgente,',
    'escríbanos por WhatsApp' => 'scrivici su WhatsApp',
    'Elija su plan, pague por transferencia y' => 'Scegli il tuo piano, paga con bonifico e',
    'suba el comprobante aquí mismo' => 'carica la ricevuta qui',
    ': lo activamos el mismo día.' => ': lo attiviamo lo stesso giorno.',
    '¿Dudas?' => 'Domande?',
    '¡Recibimos su comprobante! Lo revisamos y le avisamos por correo y Telegram apenas quede activa su cuenta (normalmente el mismo día).' => 'Abbiamo ricevuto la tua ricevuta! La verifichiamo e ti avvisiamo via e-mail e Telegram appena il tuo account sarà attivo (di solito lo stesso giorno).',
    'Ya tiene un comprobante por revisar. Le avisamos apenas lo aprobemos (normalmente el mismo día).' => 'Hai già una ricevuta in verifica. Ti avviseremo appena approvata (di solito lo stesso giorno).',
    'Adjunte la foto o captura del comprobante de la transferencia (JPG o PNG).' => 'Allega la foto o lo screenshot della ricevuta del bonifico (JPG o PNG).',
    'Elija el plan que quiere contratar.' => 'Scegli il piano che vuoi attivare.',
    'Elija por cuánto tiempo va a pagar.' => 'Scegli per quanto tempo pagherai.',
    'Solo el administrador puede contratar o renovar el plan.' => 'Solo l\'amministratore può attivare o rinnovare il piano.',
    'Su demo terminó el {n}-{n}-{n}. El panel está en solo lectura: contrate su plan en Mi plan y sigue con todo lo que cargó.' => 'La tua demo è terminata il {n}-{n}-{n}. Il pannello è in sola lettura: attiva il tuo piano in Il mio piano e continua con tutto ciò che hai caricato.',
    '💵 Contratar mi plan' => '💵 Attiva il mio piano',
    '💵 Renovar ahora' => '💵 Rinnova ora',
    '📤 Contratar mi plan y subir el comprobante' => '📤 Attiva il mio piano e carica la ricevuta',
    '📤 Renovar y subir el comprobante' => '📤 Rinnova e carica la ricevuta',
    '💵 Contrate o renueve sin salir del sistema' => '💵 Attiva o rinnova senza uscire dal sistema',
    'En ⭐ Mi plan ahora puede elegir su plan, transferir y subir la foto del comprobante. Lo revisamos y su cuenta queda activa el mismo día; le avisamos por correo y Telegram. Si está en demo, al contratar sigue con todo lo que ya cargó.' => 'In ⭐ Il mio piano ora puoi scegliere il piano, fare il bonifico e caricare la foto della ricevuta. La verifichiamo e il tuo account viene attivato lo stesso giorno; ti avvisiamo via e-mail e Telegram. Se sei in demo, attivando il piano conservi tutto ciò che hai caricato.',
    '✉️ Avisos por correo' => '✉️ Avvisi via e-mail',
    'Además de Telegram, ahora recibe por correo la bienvenida con sus accesos, los avisos de vencimiento y la confirmación de cada pago. Revise que el correo de contacto de su cuenta esté bien (Parámetros).' => 'Oltre a Telegram, ora ricevi via e-mail il benvenuto con i tuoi accessi, gli avvisi di scadenza e la conferma di ogni pagamento. Controlla che l\'e-mail di contatto del tuo account sia corretta (Parametri).',
    // (v34) ciclismo UCI: ruta, MTB, pista, BMX y freestyle
