    'MTB' => 'MTB',
    'Ciclismo de ruta · Reglas UCI: vuelta por etapas, mismo tiempo, bonificaciones, puntos, montaña, mejor joven y equipos.' => 'Ciclismo su strada · Regole UCI: corse a tappe, stesso tempo, abbuoni, punti, montagna, miglior giovane e squadre.',
    'Ciclismo de montaña (MTB) · XCO por vueltas (regla del 80 %), descenso con la mejor bajada y enduro por tramos.' => 'Mountain bike (MTB) · XCO a giri (regola dell\'80 %), discesa con la manche migliore ed enduro a prove speciali.',
    'Ciclismo de pista · Velocidad, keirin, persecución, scratch, puntos, eliminación y omnium con las reglas UCI.' => 'Ciclismo su pista · Velocità, keirin, inseguimento, scratch, punti, eliminazione e omnium con le regole UCI.',
