    'Carrera de un día: 1. Vuelta por etapas: el número de etapas. Cada carrera puede tener las suyas.' => 'Gara di un giorno: 1. Corsa a tappe: il numero di tappe. Ogni gara può avere le sue.',
    'XCO: 1. Descenso: normalmente 2 bajadas. Enduro: los tramos. Cada carrera puede tener las suyas.' => 'XCO: 1. Discesa: di solito 2 manche. Enduro: le prove. Ogni gara può avere le sue.',
    'Mejor joven: hasta cuántos años' => 'Miglior giovane: fino a quanti anni',
    'UCI: sub-23 = hasta 22 años cumplidos en el año. 0 = sin clasificación del joven.' => 'UCI: under 23 = fino a 22 anni compiuti nell\'anno. 0 = senza classifica del giovane.',
    'Para la clasificación del mejor joven (sub-23).' => 'Per la classifica del miglior giovane (under 23).',
