    'Mismo tiempo' => 'Stesso tempo',
    'Fuera de control: % sobre el tiempo del ganador (0 = sin límite)' => 'Tempo massimo: % sul tempo del vincitore (0 = senza limite)',
    'Segundos que se restan al 1.°, 2.°, 3.° en la meta' => 'Secondi tolti al 1°, 2°, 3° all\'arrivo',
    'Los que llegan con menos de 1 s del de adelante reciben el mismo tiempo' => 'Chi arriva a meno di 1 s da quello davanti riceve lo stesso tempo',
    'Guardar etapas' => 'Salva tappe',
    'En línea:' => 'In linea:',
    'llegada normal con bonificaciones (UCI: 10-6-4 s) y mismo tiempo para el grupo.' => 'arrivo normale con abbuoni (UCI: 10-6-4 s) e stesso tempo per il gruppo.',
    'Contrarreloj individual:' => 'Cronometro individuale:',
    'sin bonificaciones.' => 'senza abbuoni.',
    'Contrarreloj por equipos:' => 'Cronometro a squadre:',
    'el tiempo del equipo se toma en su 3.er corredor.' => 'il tempo della squadra si prende sul 3° corridore.',
    'Critérium:' => 'Criterium:',
    'gana quien suma más puntos. Límite %: los que llegan más allá de ese porcentaje del tiempo del ganador quedan fuera de control (OTL) y salen de la general (UCI usa entre 8 % y 20 % según la etapa).' => 'vince chi somma più punti. Limite %: chi arriva oltre quella percentuale del tempo del vincitore è fuori tempo massimo (OTL) ed esce dalla generale (l\'UCI usa dall\'8 % al 20 % secondo la tappa).',
    'Ruta:' => 'Strada:',
    'escriba el tiempo real de llegada de cada uno; el sistema aplica solo el mismo tiempo del grupo, las bonificaciones de meta, los puntos y el fuera de control según la configuración de cada etapa. En ⚑ cargue las bonificaciones y puntos de los sprints intermedios y los puntos de montaña.' => 'scrivi il tempo reale d\'arrivo di ciascuno; il sistema applica da solo lo stesso tempo del gruppo, gli abbuoni, i punti e il tempo massimo secondo la configurazione di ogni tappa. In ⚑ inserisci abbuoni e punti dei traguardi volanti e i punti della montagna.',
    'XCO:' => 'XCO:',
    'en «vueltas» ponga las vueltas que completó; si el comisario lo retiró por la regla del 80 % o fue doblado, ponga su tiempo y sus vueltas (queda clasificado detrás, con «−N vueltas»).' => 'in «giri» inserisci i giri completati; se il commissario lo ha fermato per la regola dell\'80 % o è stato doppiato, inserisci tempo e giri (è classificato dietro, con «−N giri»).',
    'Bonificación en sprints intermedios (s)' => 'Abbuono nei traguardi volanti (s)',
