    'No hay ciclistas jóvenes en la general.' => 'Nessun giovane nella generale.',
    'Fuera de control (OTL)' => 'Fuori tempo massimo (OTL)',
    'Reglas de la UCI: la general suma los tiempos de las etapas menos las bonificaciones; los que llegan en el mismo grupo (menos de 1 s) reciben el mismo tiempo (m.t.). OTL: fuera de control · DNF: no terminó · DSQ: descalificado · DNS: no largó.' => 'Regole UCI: la generale somma i tempi delle tappe meno gli abbuoni; chi arriva nello stesso gruppo (meno di 1 s) riceve lo stesso tempo (s.t.). OTL: fuori tempo massimo · DNF: ritirato · DSQ: squalificato · DNS: non partito.',
