    'Ruta: etapas en línea, contrarreloj y critérium, bonificaciones, mismo tiempo del grupo, fuera de control y clasificaciones de puntos, montaña, mejor joven y equipos. Nuevos deportes: ciclismo de pista (velocidad, keirin, persecución, puntos, scratch, eliminación, tempo y omnium), BMX Racing (motos, cuartos, semis y final), BMX Freestyle (Park y Flatland con jueces) y MTB (cross-country por vueltas, descenso y enduro).' => 'Strada: tappe in linea, cronometro e criterium, abbuoni, stesso tempo del gruppo, tempo massimo e classifiche a punti, montagna, miglior giovane e squadre. Nuovi sport: ciclismo su pista (velocità, keirin, inseguimento, punti, scratch, eliminazione, tempo e omnium), BMX Racing (batterie, quarti, semifinali e finale), BMX Freestyle (Park e Flatland con giudici) e MTB (cross-country a giri, discesa ed enduro).',
