    'Básquet 5×5 y 3×3: cuartos, faltas personales y técnicas, tabla y estadísticas.' => 'Basket 5×5 e 3×3: quarti, falli personali e tecnici, classifica e statistiche.',
    'Vóley 6×6 por sets, con su tabla de posiciones y escuelas de vóley.' => 'Pallavolo 6×6 a set, con classifica e scuole di pallavolo.',
