    'Ficha de la federación' => 'Scheda della federazione',
    'El sistema ahora se arma por deporte: Fútbol, Básquet, Vóley, Ecuavóley, Ciclismo, Deportes de combate, Deportes de raqueta, Natación, Atletismo, Bolos y Automovilismo. Agregue a su cuenta los deportes que necesite con descuento desde el segundo módulo; todo queda en el mismo panel. Cada deporte pide sus propios datos y documentos (licencia, certificado médico, peso, grado…).' => 'Il sistema ora si compone per sport: Calcio, Basket, Pallavolo, Ecuavolley, Ciclismo, Sport da combattimento, Sport di racchetta, Nuoto, Atletica, Bowling e Automobilismo. Aggiungi al tuo account gli sport che ti servono con uno sconto dal secondo modulo; tutto resta nello stesso pannello. Ogni sport chiede i propri dati e documenti (tessera, certificato medico, peso, grado…).',
    // (v35) módulos separados
    'Deportes de raqueta' => 'Sport di racchetta',
    'Automovilismo' => 'Automobilismo',
    'Tenis, pádel y tenis de mesa: llaves con cabezas de serie, marcador por sets, todos contra todos y ranking.' => 'Tennis, padel e tennis tavolo: tabelloni con teste di serie, punteggio a set, gironi all\'italiana e ranking.',
    'Pruebas por estilo y distancia (libre, espalda, pecho, mariposa, combinado y relevos), por edad y rama, con medallero y puntos por club.' => 'Gare per stile e distanza (stile libero, dorso, rana, farfalla, misti e staffette), per età e genere, con medagliere e punti per club.',
    'Carreras, vallas, saltos, lanzamientos y relevos por categoría y rama, con medallero, puntos por club y mejores marcas.' => 'Corse, ostacoli, salti, lanci e staffette per categoria e genere, con medagliere, punti per club e migliori prestazioni.',
    'Jornadas con líneas, handicap automático, récords y clasificación individual y por clubes.' => 'Giornate con partite, handicap automatico, record e classifiche individuali e per club.',
    'Autocross por mangas con categorías por cilindrada y motor, conos, penalizaciones y campeonato por puntos o tiempo.' => 'Autocross a manche con categorie per cilindrata e motore, coni, penalità e campionato a punti o a tempo.',
