    'Atletismo, Carreras de ruta, trail y cross' => 'Atletica, Corse su strada, trail e cross',
    'Tenis, Pádel, Tenis de mesa, Squash' => 'Tennis, Padel, Tennis tavolo, Squash',
    'Tenis, pádel, tenis de mesa y squash: llaves con cabezas de serie, grupos, consolación, Monrad, escalera del club, marcador por sets o games a 11 y ranking del circuito.' => 'Tennis, padel, tennis tavolo e squash: tabelloni con teste di serie, gironi, consolazione, Monrad, scala del club, punteggio a set o game a 11 e ranking del circuito.',
    'Torneos por sistema suizo (Buchholz), todos contra todos o llave, con ELO, categorías Sub 10 a Sub 18 y ranking del circuito.' => 'Tornei a sistema svizzero (Buchholz), all\'italiana o a eliminazione, con Elo, categorie Under 10 a Under 18 e ranking del circuito.',
    'Torneos de videojuegos 1 vs 1 o 2 vs 2 (eFootball, FIFA/FC y otros): grupos, llaves con penales, tabla por goles y ranking.' => 'Tornei di videogiochi 1 contro 1 o 2 contro 2 (eFootball, FIFA/FC e altri): gironi, tabelloni con rigori, classifica per gol e ranking.',
    'Competencias con las reglas de la IWF: categorías de peso corporal, 3 intentos de arranque y 3 de envión, total, medallero y puntos por club.' => 'Gare con le regole IWF: categorie di peso, 3 prove di strappo e 3 di slancio, totale, medagliere e punti per club.',
    'Triatlón, duatlón y acuatlón: tiempo por segmento y transiciones, clasificación general, por rama y por grupo de edad.' => 'Triathlon, duathlon e aquathlon: tempo per frazione e transizioni, classifica assoluta, per sesso e per fascia d\'età.',
    'Balonmano (handball) 7 contra 7: goles, goles de 7 metros, exclusiones de 2 minutos, amonestaciones y descalificaciones, vocalía en vivo, tabla 2-1-0 y goleadores.' => 'Pallamano 7 contro 7: gol, gol dai 7 metri, esclusioni di 2 minuti, ammonizioni e squalifiche, referto in diretta, classifica 2-1-0 e marcatori.',
    'Béisbol (9 entradas) y softbol (7 entradas): carreras por entrada, hits, errores, jonrones y ponches, pizarra del partido, vocalía en vivo y tabla de ganados.' => 'Baseball (9 inning) e softball (7 inning): punti per inning, valide, errori, fuoricampo e strikeout, tabellone della partita, referto in diretta e classifica delle vittorie.',
    'Pista y campo con las reglas de World Athletics (series y final, viento, concursos con intentos, salto alto y garrocha por alturas, heptatlón y decatlón) y carreras de ruta, trail y cross con tiempo de chip, grupos de edad, diplomas y equipos.' => 'Pista e pedana con le regole di World Athletics (batterie e finale, vento, concorsi con prove, alto e asta per altezze, eptathlon e decathlon) e corse su strada, trail e cross con chip, fasce d\'età, diplomi e squadre.',
    'Squash · Games a 11: grupos y luego llave, Monrad con todos los puestos, escalera del club y ranking.' => 'Squash · Game a 11: gironi e poi tabellone, Monrad con tutte le posizioni, scala del club e ranking.',
    'Ajedrez · Sistema suizo con Buchholz, ELO y todos contra todos.' => 'Scacchi · Sistema svizzero con Buchholz, Elo e all\'italiana.',
    'E-sports · eFootball 1 vs 1: grupos, llave con penales y tercer puesto.' => 'E-sport · eFootball 1 contro 1: gironi, tabellone con rigori e 3° posto.',
    'Carreras de ruta, trail y cross · 10K con tiempo de chip, grupos de edad, equipos, buscador por dorsal y diplomas.' => 'Corse su strada, trail e cross · 10 km con chip, fasce d\'età, squadre, ricerca per pettorale e diplomi.',
    'Levantamiento de pesas · Arranque y envión con 3 intentos, total y peso corporal (IWF).' => 'Sollevamento pesi · Strappo e slancio con 3 prove, totale e peso corporeo (IWF).',
    'Triatlón · Natación, transiciones, ciclismo y carrera, con grupos de edad.' => 'Triathlon · Nuoto, transizioni, bici e corsa, con fasce d\'età.',
    'Grupos y luego llave' => 'Gironi e poi tabellone',
    'Llave con consolación' => 'Tabellone con consolazione',
    'Llave con todos los puestos (Monrad)' => 'Tabellone con tutte le posizioni (Monrad)',
    'Sistema suizo (por rondas)' => 'Sistema svizzero (a turni)',
    'Escalera de desafíos (ranking del club)' => 'Scala di sfide (ranking del club)',
    'El que pierde queda fuera. Cabezas de serie separados y pases directos repartidos.' => 'Chi perde è fuori. Teste di serie separate e bye distribuiti.',
    'Todos juegan contra todos; gana la tabla.' => 'Tutti giocano contro tutti; decide la classifica.',
    'Grupos de 3 a 5 (todos contra todos) y los primeros de cada grupo pasan a una llave final. Es el formato de los nacionales de squash.' => 'Gironi da 3 a 5 (all\'italiana) e i primi di ogni girone passano a un tabellone finale. È il formato dei campionati nazionali di squash.',
    'Llave principal y una llave de consolación (plate) para los que pierden su primer partido: todos juegan al menos dos.' => 'Tabellone principale e uno di consolazione (plate) per chi perde la prima partita: tutti giocano almeno due partite.',
    'Nadie queda fuera: ganadores y perdedores siguen jugando en sub-llaves hasta definir todos los puestos (1.º al último).' => 'Nessuno è eliminato: vincitori e perdenti continuano in sotto-tabelloni fino a definire tutte le posizioni (dalla 1ª all\'ultima).',
    'Por rondas: en cada ronda se empareja a los de igual puntaje sin repetir rival. Ideal para ajedrez y para muchos inscritos.' => 'A turni: ogni turno abbina i giocatori con lo stesso punteggio senza ripetere l\'avversario. Ideale per gli scacchi e per molti iscritti.',
    'Ranking permanente del club: se desafía a alguien hasta N puestos arriba; si gana, toma su puesto.' => 'Ranking permanente del club: si sfida qualcuno fino a N posizioni sopra; se vince, prende il suo posto.',
    'Grupos: jugadores por grupo' => 'Gironi: giocatori per girone',
    'Grupos: pasan a la llave' => 'Gironi: passano al tabellone',
    'Solo «Grupos y luego llave». Squash: 3 (máximo 5).' => 'Solo «Gironi e poi tabellone». Squash: 3 (massimo 5).',
    'Los primeros de cada grupo.' => 'I primi di ogni girone.',
    'Suizo: rondas' => 'Svizzero: turni',
    'Vacío = según los inscritos (8 → 4 rondas).' => 'Vuoto = in base agli iscritti (8 → 4 turni).',
    'Escalera: desafiar hasta' => 'Scala: sfidare fino a',
    'Puestos más arriba.' => 'Posizioni sopra.',
