    'El ranking aparece cuando termina al menos una categoría de un campeonato (la final jugada o todas las fechas).' => 'Il ranking appare quando finisce almeno una categoria di un campionato (finale giocata o tutte le giornate).',
    'Suma los puntos de todos los campeonatos de {s} de su cuenta, por categoría (mismo nombre de categoría). Cada campeonato da puntos según el puesto final, multiplicados por su factor (por ejemplo: nacional 100 %, regional 50 %). Se cambian en «Reglas y configuración».' => 'Somma i punti di tutti i campionati di {s} del suo account, per categoria (stesso nome). Ogni campionato dà punti in base alla posizione finale, moltiplicati per il suo coefficiente (es.: nazionale 100 %, regionale 50 %). Si cambiano in «Regole e configurazione».',
