    'Concurso (World Athletics)' => 'Concorso (World Athletics)',
    'en cada intento escriba la marca en metros (ej:' => 'in ogni prova scriva la misura in metri (es.:',
    'si fue nulo o' => 'se nulla o',
    'si pasó. Gana la mejor marca; si empatan, decide la segunda mejor.' => 'se passata. Vince la miglior misura; in caso di parità decide la seconda migliore.',
    'si pasó. Después de {n} intentos, los {n} mejores hacen {n} más (sus casillas se marcan en verde). Gana la mejor marca; si empatan, decide la segunda mejor.' => 'se passata. Dopo {n} prove, i {n} migliori ne fanno altre {n} (le caselle diventano verdi). Vince la miglior misura; in caso di parità decide la seconda migliore.',
