    'Pesas (IWF)' => 'Sollevamento pesi (IWF)',
    'escriba el peso corporal del pesaje y los kilos de cada intento:' => 'scriva il peso corporeo della pesata e i chili di ogni prova:',
    'escriba el peso corporal del pesaje (hasta {n} kg) y los kilos de cada intento:' => 'scriva il peso corporeo della pesata (fino a {n} kg) e i chili di ogni prova:',
    'escriba el peso corporal del pesaje (más de {n} kg) y los kilos de cada intento:' => 'scriva il peso corporeo della pesata (oltre {n} kg) e i chili di ogni prova:',
