    '(chip, desde que cruzó la salida). Clasifica por tiempo oficial. Grupos de edad: {s} (por rama).' => '(chip, da quando ha passato la partenza). Classifica per tempo ufficiale. Fasce d\'età: {s} (per sesso).',
    '(chip, desde que cruzó la salida). Clasifica por tiempo neto. Grupos de edad: {s} (por rama). Por equipos suman los {s} primeros de cada club.' => '(chip, da quando ha passato la partenza). Classifica per tempo netto. Fasce d\'età: {s} (per sesso). A squadre si sommano i primi {s} di ogni club.',
    '(chip, desde que cruzó la salida). Clasifica por tiempo oficial. Grupos de edad: {s} (por rama). Por equipos suman los {s} primeros de cada club.' => '(chip, da quando ha passato la partenza). Classifica per tempo ufficiale. Fasce d\'età: {s} (per sesso). A squadre si sommano i primi {s} di ogni club.',
    'Por pruebas ({n} m libre, {n} m planos, salto largo, velocidad, keirin, omnium, BMX, park...) separadas por categoría de edad y rama. Se cargan los tiempos, distancias, puestos o notas y el sistema arma los resultados de cada prueba con las reglas de cada deporte (en ciclismo, las de la UCI), el' => 'Per gare ({n} m stile libero, {n} m piani, salto in lungo, velocità, keirin, omnium, BMX, park...) divise per categoria d\'età e sesso. Si inseriscono tempi, distanze, posizioni o punteggi e il sistema compone i risultati di ogni gara con le regole di ogni sport (nel ciclismo, quelle UCI), il',
