    'Si lo desmarca, se cobran todos los módulos además del plan.' => 'Se la deseleziona, tutti i moduli si pagano oltre al piano.',
    'Se aplica a cada módulo adicional ({n} = sin descuento).' => 'Si applica a ogni modulo aggiuntivo ({n} = nessuno sconto).',
    '({n} gratis)' => '({n} gratis)',
