    '(el plan incluye uno; cada deporte adicional con {n} % de descuento)' => '(il piano ne include uno; ogni sport aggiuntivo con il {n}% di sconto)',
    'El total que paga el cliente = precio del plan (Básico, Profesional…) + lo de esta columna. En {n} y {n} meses se aplica la misma rebaja del plan (meses gratis).' => 'Il totale pagato dal cliente = prezzo del piano (Base, Professionale…) + questa colonna. A {n} e {n} mesi si applica lo stesso sconto del piano (mesi gratis).',
    'Son los valores con los que empieza cada campeonato nuevo de este deporte en todas las cuentas. Deje vacío para usar el valor de fábrica (entre paréntesis). Cada cuenta puede cambiarlos después en su campeonato.' => 'Sono i valori con cui parte ogni nuovo campionato di questo sport in tutti gli account. Lasci vuoto per usare il valore di fabbrica (tra parentesi). Ogni account può cambiarli poi nel suo campionato.',
    '— de fábrica —' => '— di fabbrica —',
    'Nombre, cédula, foto, fecha de nacimiento y club ya están en cada ficha: aquí van los datos propios del deporte.' => 'Nome, documento, foto, data di nascita e club sono già in ogni scheda: qui vanno i dati propri dello sport.',
    'Nuevo documento (ej: Ficha de la federación)' => 'Nuovo documento (es.: scheda della federazione)',
    'Para quitar un documento, borre su nombre. Con «tiene vencimiento» se pide la fecha y, cuando pasa, vuelve a aparecer como faltante (ej: certificado médico anual).' => 'Per togliere un documento, cancelli il nome. Con «ha scadenza» si chiede la data e, quando passa, torna a risultare mancante (es.: certificato medico annuale).',
    'Se piden en la ficha del jugador, del competidor o del alumno de este deporte y en la inscripción en línea. Lo' => 'Si chiedono nella scheda del giocatore, del concorrente o dell\'allievo di questo sport e nell\'iscrizione online. Ciò',
    'que falte aparece como «⚠ falta» en las listas, y en la inscripción en línea no se puede enviar sin eso.' => 'che manca appare come «⚠ manca» negli elenchi, e l\'iscrizione online non si può inviare senza.',
    'Para que el panel siga funcionando sin interrupciones, renueve antes de esa fecha.' => 'Perché il pannello continui a funzionare senza interruzioni, rinnovi prima di quella data.',
    '⏰ Su suscripción de TuAcademia vence en {s} días ({s})' => '⏰ Il suo abbonamento TuAcademia scade tra {s} giorni ({s})',
    'Activa hasta el {s} (faltan {s} días)' => 'Attivo fino al {s} (mancano {s} giorni)',
    'Puede crear {n} campeonato a la vez (en curso) · lleva {n} · no le quedan más' => 'Può creare {n} campionato alla volta (in corso) · ne ha {n} · non ne restano',
    'El sistema se vende por deporte. Cada cuenta tiene sus módulos; quien compra más de uno lo ve todo junto en el mismo panel. Aquí maneja precios, requisitos, reglas por defecto, qué módulos tiene cada cuenta y las demos de cada deporte.' => 'Il sistema si vende per sport. Ogni account ha i suoi moduli; chi ne compra più di uno vede tutto insieme nello stesso pannello. Qui gestisce prezzi, requisiti, regole predefinite, quali moduli ha ogni account e le demo di ogni sport.',
    '(natación, atletismo, ciclismo de pista, bmx racing, bmx freestyle, carreras de ruta, trail y cross, levantamiento de pesas, triatlón, duatlón y acuatlón)' => '(nuoto, atletica, ciclismo su pista, BMX racing, BMX freestyle, corse su strada, trail e cross, sollevamento pesi, triathlon, duathlon e aquathlon)',
