    'Precios en dólares. En la demo tiene todos los módulos (el fixture para imprimir y el esquema del campeonato son exclusivos del plan Profesional). ¿Necesita algo especial? Consúltenos.' => 'Prezzi in dollari. Nella demo ha tutti i moduli (il calendario da stampare e lo schema del campionato sono esclusivi del piano Professionale). Le serve qualcosa di speciale? Ci contatti.',
    '· 🎓 Escuela multideporte (fútbol, básquet, vóley, boxeo, natación, taekwondo y tenis) ·' => '· 🎓 Scuola multisport (calcio, basket, pallavolo, pugilato, nuoto, taekwondo e tennis) ·',
    'usa las reglas de la UCI (etapas, mismo tiempo, bonificaciones, puntos, montaña, mejor joven y equipos); en' => 'usa le regole UCI (tappe, stesso tempo, abbuoni, punti, montagna, miglior giovane e squadre); nel',
