    'Olimpiadas y juegos multideportivos' => 'Olimpiadi e giochi multisport',
    'Olimpiadas interempresas, interbancarias o intercolegiales: varios deportes a la vez, delegaciones que inscriben a su gente con su propio enlace, una ficha por deportista, medallero general, tabla de puntos configurable y administradores por evento.' => 'Olimpiadi tra aziende, banche o scuole: più sport insieme, delegazioni che iscrivono la loro gente con il proprio link, una scheda per atleta, medagliere generale, classifica a punti configurabile e amministratori per evento.',
    'Juegos multideportivos: delegaciones y medallero' => 'Giochi multisport: delegazioni e medagliere',
    'Eventos multideportivos: disciplinas, delegaciones, deportistas, medallero y configuración.' => 'Eventi multisport: discipline, delegazioni, atleti, medagliere e configurazione.',
    'Administrador de evento (olimpiadas)' => 'Amministratore di evento (olimpiadi)',
    'Solo los eventos de olimpiadas que se le asignan: configuración, disciplinas, delegaciones, deportistas, resultados de sus campeonatos y medallero.' => 'Solo gli eventi di olimpiadi che gli vengono assegnati: configurazione, discipline, delegazioni, atleti, risultati dei loro campionati e medagliere.',
    'Administrador de evento (olimpiadas) — Solo los eventos de olimpiadas que se le asignan: configuración, disciplinas, delegaciones, deportistas, resultados de sus campeonatos y medallero.' => 'Amministratore di evento (olimpiadi) — Solo gli eventi di olimpiadi che gli vengono assegnati: configurazione, discipline, delegazioni, atleti, risultati dei loro campionati e medagliere.',
    '🏅 Olimpiadas y juegos multideportivos' => '🏅 Olimpiadi e giochi multisport',
    'Organice olimpiadas interempresas, interbancarias, intercolegiales o de barrio: varios deportes a la vez, cada empresa o colegio como una' => 'Organizzi olimpiadi tra aziende, banche, scuole o di quartiere: più sport insieme, ogni azienda o scuola come una',
