    '✓ terminó' => '✓ finito',
    'Cada disciplina es un campeonato de la cuenta con sus propias reglas, fixture, llaves o pruebas. Aquí se define su fecha, horario y lugar (para el programa y para avisar cruces de horario), si es solo de varones o damas, cuánto vale en la tabla (factor) y el cupo por delegación.' => 'Ogni disciplina è un campionato dell\'account con le sue regole, calendario, tabelloni o gare. Qui si definiscono data, orario e luogo (per il programma e per avvisare delle sovrapposizioni), se è solo maschile o femminile, quanto vale in classifica (coefficiente) e i posti per delegazione.',
