    '(v{n}) Nota del dominio incluido (sale con * en los planes)' => '(v{n}) Nota del dominio incluso (compare con * nei piani)',
    '* El dominio propio viene incluido al pagar el plan por {n} año. El dominio es propiedad de tupass.com; la organización lo usa mientras mantenga su plan al día.' => '* Il dominio proprio è incluso pagando il piano per {n} anno. Il dominio è di proprietà di tupass.com; l\'organizzazione lo usa finché mantiene il piano in regola.',
    '* El dominio propio viene incluido al pagar el plan por {n} año. La academia lo usa mientras mantenga su plan al día.' => '* Il dominio proprio è incluso pagando il piano per {n} anno. L\'accademia lo usa finché mantiene il piano in regola.',
    'Desde ${n} al mes. Puede pagar mensual, semestral (ahorra {n} mes) o anual (ahorra {n} meses), por transferencia o con tarjeta. Primero le preparamos una demo para que lo conozca.' => 'Da ${n} al mese. Può pagare mensile, semestrale (risparmi {n} mese) o annuale (risparmi {n} mesi), con bonifico o carta. Prima le prepariamo una demo per conoscerlo.',
    'Desde ${n} por {n} meses. Puede pagar mensual, semestral (ahorra {n} mes) o anual (ahorra {n} meses), por transferencia o con tarjeta. Primero le preparamos una demo para que lo conozca.' => 'Da ${n} per {n} mesi. Può pagare mensile, semestrale (risparmi {n} mese) o annuale (risparmi {n} mesi), con bonifico o carta. Prima le prepariamo una demo per conoscerlo.',
    'en cada plan. Se mantiene el ahorro de {n} mes en el semestre y de {n} meses en el año.' => 'in ogni piano. Resta il risparmio di {n} mese nel semestre e di {n} mesi nell\'anno.',
    'Poner {n} mes de ahorro' => 'Mettere {n} mese di risparmio',
    'Poner {n} meses de ahorro' => 'Mettere {n} mesi di risparmio',
    'Los límites y módulos se aplican solos a cada liga o escuela según su plan (en la demo tienen todo). {n} = sin límite. Un precio en {n} = ese período no se ofrece. En Ligas → Editar se encienden o apagan los módulos de cada cliente.' => 'Limiti e moduli si applicano da soli a ogni lega o scuola secondo il piano (nella demo hanno tutto). {n} = senza limite. Un prezzo a {n} = quel periodo non è offerto. In Leghe → Modifica si accendono o spengono i moduli di ogni cliente.',
