    'Guardar funciones y precios' => 'Salva funzioni e prezzi',
    'Lo básico (equipos, campeonatos, alumnos, pagos con recibo, página pública…) lo tiene todo cliente. Cada función de aquí se cobra aparte si no está en su plan. Qué trae cada plan se cambia en' => 'Ogni cliente ha le funzioni di base (squadre, campionati, allievi, pagamenti con ricevuta, pagina pubblica…). Ogni funzione qui si paga a parte se non è nel suo piano. Cosa include ogni piano si cambia in',
    '. Lo encendido de cada cliente, en Ligas → Editar → Módulos de la cuenta. Apagar nunca borra datos.' => '. Ciò che è acceso per ogni cliente, in Leghe → Modifica → Moduli dell\'account. Spegnere non cancella mai i dati.',
    'Los clientes los piden desde ⭐ Mi plan. También llegan al Panel Tukán Central (Solicitudes → «Cambio de módulos»).' => 'I clienti li chiedono da ⭐ Il mio piano. Arrivano anche al Pannello Tukán Central (Richieste → «Cambio moduli»).',
    'No hay pedidos.' => 'Non ci sono richieste.',
    'Crear demo' => 'Crea demo',
    'En ⭐ Mi plan → Mis módulos ve las funciones que tiene encendidas y las que puede agregar, con su precio. Toque «Pedir este módulo» y se lo encendemos (normalmente el mismo día). Si un módulo se apaga, sus datos no se borran.' => 'In ⭐ Il mio piano → I miei moduli vede le funzioni accese e quelle che può aggiungere, con il prezzo. Tocchi «Richiedi questo modulo» e lo accendiamo (di solito in giornata). Se un modulo si spegne, i suoi dati non vengono cancellati.',
    'en la prueba gratis tienen todo' => 'nella demo hanno tutto',
    // (Anexo B, 18 oct 2026) módulos por cliente y «todo se pide demo» (sin prueba gratis)
    '${n} (ahorra {n} meses) + dominio incluido' => '${n} (risparmi {n} mesi) + dominio incluso',
    'Nombre, disciplinas, pensión y listo (pida su demo y la preparamos con usted).' => 'Nome, discipline, retta ed è pronto (richieda la sua demo e la prepariamo con lei).',
    'Precios en dólares. En la demo tiene todo. ¿Necesita algo especial? Consúltenos.' => 'Prezzi in dollari. Nella demo ha tutto. Le serve qualcosa di speciale? Ci consulti.',
    'Desde ${n} al mes. Puede pagar mensual, semestral (paga {n} meses y recibe {n}) o anual (paga {n} y recibe {n}, más dominio propio). Primero le preparamos una demo.' => 'Da ${n} al mese. Può pagare mensile, semestrale (paga {n} mesi e ne riceve {n}) o annuale (paga {n} e ne riceve {n}, più dominio proprio). Prima le prepariamo una demo.',
    // (20 oct 2026) sin «gratis»: textos nuevos
    'Sin costo' => 'Senza costi',
    'Sin costo y sin apuestas' => 'Senza costi e senza scommesse',
    'Le llega un aviso al celular con cada gol, el resultado final y los horarios de Atlético Chimborazo (Liga Demo TuAcademia). No necesita Telegram ni WhatsApp.' => 'Riceve un avviso sul cellulare a ogni gol, con il risultato finale e gli orari di Atlético Chimborazo (Liga Demo TuAcademia). Senza Telegram né WhatsApp.',
    'Le llega un aviso al celular con cada gol, el resultado final y los horarios de Atlético Chimborazo. No necesita Telegram ni WhatsApp.' => 'Riceve un avviso sul cellulare a ogni gol, con il risultato finale e gli orari di Atlético Chimborazo. Senza Telegram né WhatsApp.',
    'Le llega un aviso al celular con cada gol, el resultado final y los horarios de Deportivo Los Andes (Liga Demo TuAcademia). No necesita Telegram ni WhatsApp.' => 'Riceve un avviso sul cellulare a ogni gol, con il risultato finale e gli orari di Deportivo Los Andes (Liga Demo TuAcademia). Senza Telegram né WhatsApp.',
    'Le llega un aviso al celular con cada gol, el resultado final y los horarios de Deportivo Los Andes. No necesita Telegram ni WhatsApp.' => 'Riceve un avviso sul cellulare a ogni gol, con il risultato finale e gli orari di Deportivo Los Andes. Senza Telegram né WhatsApp.',
    'Le llega un aviso al celular con cada gol, el resultado final y los horarios de Estrella del Sur. No necesita Telegram ni WhatsApp.' => 'Riceve un avviso sul cellulare a ogni gol, con il risultato finale e gli orari di Estrella del Sur. Senza Telegram né WhatsApp.',
    'Le llega un aviso al celular con cada gol, el resultado final y los horarios de Leones. No necesita Telegram ni WhatsApp.' => 'Riceve un avviso sul cellulare a ogni gol, con il risultato finale e gli orari di Leones. Senza Telegram né WhatsApp.',
    'Le llega un aviso al celular con cada gol, el resultado final y los horarios de Pumas. No necesita Telegram ni WhatsApp.' => 'Le arriva un avviso sul cellulare con ogni gol, il risultato finale e gli orari dei Pumas. Senza Telegram né WhatsApp.',
    'Le llega un aviso al celular con cada gol, el resultado final y los horarios de Real Cotopaxi. No necesita Telegram ni WhatsApp.' => 'Riceve un avviso sul cellulare a ogni gol, con il risultato finale e gli orari di Real Cotopaxi. Senza Telegram né WhatsApp.',
    'Le llega un aviso al celular con cada gol, el resultado final y los horarios de Tigres. No necesita Telegram ni WhatsApp.' => 'Le arriva un avviso sul cellulare con ogni gol, il risultato finale e gli orari dei Tigres. Senza Telegram né WhatsApp.',
    'Le llega un aviso al celular con cada gol, el resultado final y los horarios de Águilas FC. No necesita Telegram ni WhatsApp.' => 'Riceve un avviso sul cellulare a ogni gol, con il risultato finale e gli orari di Águilas FC. Senza Telegram né WhatsApp.',
    'Los hinchas pronostican los resultados y compiten en una tabla, sin costo y sin apuestas.' => 'I tifosi pronosticano i risultati senza costi e competono in una classifica. Senza scommesse.',
    'Participar (sin costo)' => 'Partecipa (senza costi)',
    'Se carga al equipo que lo recibe. {n} = sin costo.' => 'Viene addebitato alla squadra che lo riceve. {n} = senza costi.',
    'Se carga al equipo que recibe al jugador. {n} = sin costo. Se puede cambiar en cada pase.' => 'Viene addebitato alla squadra che riceve il giocatore. {n} = senza costi. Si può modificare a ogni trasferimento.',
    'Usted (o el representante de un menor de edad) puede pedir ver, corregir o borrar sus datos personales, entre otros derechos. No tiene costo.' => 'Lei (o il genitore/tutore di un minorenne) può chiedere di vedere, correggere o cancellare i suoi dati personali, tra gli altri diritti. Non ha costi.',
    'ver, corregir o borrar sus datos personales, entre otros derechos. No tiene costo.' => 'vedere, correggere o cancellare i suoi dati personali, tra gli altri diritti. Non ha costi.',
    '🎁 Cortesías (sin costo)' => '🎁 Omaggi (senza costi)',
    'o el Panel Tukán Central). No hay registro abierto.' => 'o il Pannello Tukán Central). Non c\'è registrazione libera.',
    'No hay registro abierto: los interesados piden la demo en' => 'Non c\'è registrazione libera: gli interessati chiedono la demo su',
    // (20 oct 2026) ingreso de TuAcademia: texto propio
    'Aquí ingresan con su correo y contraseña el dueño o la dueña de la academia, la secretaría y los profesores. Los padres de familia ingresan en' => 'Qui accedono con e-mail e password il titolare dell\'accademia, la segreteria e gli insegnanti. I genitori accedono dal',
